using Harborline.Foundation.Forms;
using Harborline.Foundation.Forms.Exceptions;
using Harborline.Foundation.Forms.Models;
using Harborline.Contracts.Fields;
using Harborline.Foundation.Authorization;
using Harborline.Foundation.MultiTenancy;

namespace Harborline.Foundation.Forms.Engine.Authoring;

/// <summary>
/// Fail-closed implementation of the Harborline App authoring-host save-and-publish sequence.
/// </summary>
public sealed class FormDefinitionAuthoringPublisher(
    IFormDefinitionStore store,
    IFormDefinitionPolicyAdmission policyAdmission,
    IFormFieldBindingSource? fieldBindings = null,
    IFieldKindRuntime? fieldKinds = null,
    IFieldDomainRuntime? fieldDomains = null,
    IAuthenticatedActorContext? actor = null)
    : IFormDefinitionAuthoringPublisher
{
    /// <inheritdoc />
    public async ValueTask<FormDefinition> RegisterAndPublishAsync(
        FormDefinition definition,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(definition);
        cancellationToken.ThrowIfCancellationRequested();

        if (definition.Status != FormDefinitionStatus.Draft)
        {
            throw new FormDefinitionValidationException(
                definition.Id,
                $"authoring publication requires a Draft definition, but '{definition.Id}' v{definition.Version} is {definition.Status}.");
        }

        // This must remain before the first store mutation. It is the destination equivalent of
        // Harborline App's FormDefinitionPublishAdmission call in the authoring endpoint.
        RuleCompileAdmission.ValidateOrThrow(definition);
        policyAdmission.ValidateOrThrow(definition);
        if (fieldBindings is not null || fieldKinds is not null || fieldDomains is not null)
        {
            if (fieldBindings is null || fieldKinds is null || fieldDomains is null)
                throw FormFieldBinding.Refuse("field.binding_unresolved", "");
            if (string.IsNullOrWhiteSpace(actor?.UserId))
                throw FormFieldBinding.Refuse("field.value_domain_principal_required", "");
            var tenant = actor.Tenant;
            if (tenant is null || tenant.Id.IsSystemSentinel || tenant.Status != TenantStatus.Active)
                throw FormFieldBinding.Refuse("field.value_domain_tenant_required", "");
            if (tenant.Id != definition.Tenant)
                throw FormFieldBinding.Refuse("field.value_domain_tenant_mismatch", "");
            await new FormFieldBinding(fieldBindings, fieldKinds, fieldDomains)
                .ResolveAsync(new FieldDomainScope(tenant.Id, actor.UserId), definition, cancellationToken).ConfigureAwait(false);
        }

        return await store.RegisterAndPublishAsync(definition, cancellationToken).ConfigureAwait(false);
    }
}

using Harborline.Contracts.Authorization;
using Harborline.Foundation.Forms;
using Harborline.Foundation.Forms.Exceptions;
using Harborline.Foundation.Forms.Models;
using Harborline.Foundation.Forms.Engine.Security;

namespace Harborline.Foundation.Forms.Engine.Authoring;

/// <summary>Fail-closed policy admission run by an authoring host before publication.</summary>
public interface IFormDefinitionPolicyAdmission
{
    /// <summary>Validates every authored field and connector input against the runtime policy model.</summary>
    void ValidateOrThrow(FormDefinition definition);
}

/// <summary>
/// Bounded destination policy admission. It validates the same form/section/container/field grains
/// consumed by the runtime resolver without importing the aggregate legacy Governance topology.
/// </summary>
public sealed class DefaultFormDefinitionPolicyAdmission(
    IFormFieldGovernanceResolver governance) : IFormDefinitionPolicyAdmission
{
    /// <inheritdoc />
    public void ValidateOrThrow(FormDefinition definition)
    {
        ArgumentNullException.ThrowIfNull(definition);

        foreach (var fieldName in definition.Overlay.Fields.Keys)
        {
            ValidateMonotonicGrains(definition, fieldName);
            var policy = governance.Resolve(definition, fieldName);
            if (!policy.IsResolved)
            {
                throw Fail(
                    definition,
                    fieldName,
                    policy.Refusal == FormGovernanceRefusal.PolicyInvalid
                        ? "aspect.policy_invalid"
                        : "aspect.policy_unresolved");
            }
        }

        foreach (var check in definition.Overlay.AsyncChecks ?? [])
        {
            if (check.AllowsSensitiveInputs) continue;
            foreach (var fieldName in new[] { check.Field }.Concat(check.Inputs ?? []).Distinct(StringComparer.Ordinal))
            {
                if (!definition.Overlay.Fields.TryGetValue(fieldName, out var field)) continue;
                var policy = governance.Resolve(definition, fieldName);
                if (field.PiiSensitivity == PiiSensitivity.Sensitive || policy.ProtectAtRest)
                {
                    throw new FormDefinitionValidationException(
                        definition.Id,
                        $"aspect.sensitive_input_unacknowledged: async check '{check.Id}' feeds classified field '{fieldName}' to connector '{check.Connector}' without allowsSensitiveInputs.");
                }
            }
        }
    }

    private static void ValidateMonotonicGrains(FormDefinition definition, string fieldName)
    {
        var grains = EffectiveAspects(definition.Overlay, fieldName).ToArray();
        HashSet<string>? inheritedTags = null;
        HashSet<RoleReference>? inheritedReadRoles = null;
        HashSet<RoleReference>? inheritedWriteRoles = null;
        int? retentionDays = null;
        Immutability? immutability = null;
        HashSet<string>? allowedResidency = null;
        var prohibitedResidency = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        foreach (var grain in grains)
        {
            if (grain.Classification is { } classification)
            {
                var declared = classification.Tags.Select(TagKey).ToHashSet(StringComparer.Ordinal);
                if (classification.Tags.Any(tag => string.IsNullOrWhiteSpace(tag.System) || string.IsNullOrWhiteSpace(tag.Code)))
                    throw Fail(definition, fieldName, "aspect.policy_invalid");
                if (inheritedTags is not null && !inheritedTags.IsSubsetOf(declared))
                    throw Fail(definition, fieldName, "aspect.relax_forbidden");
                inheritedTags = declared;
            }

            inheritedReadRoles = NarrowRoles(definition, fieldName, inheritedReadRoles, grain.Access?.ReadRoles);
            inheritedWriteRoles = NarrowRoles(definition, fieldName, inheritedWriteRoles, grain.Access?.WriteRoles);

            if (grain.Lifecycle?.Retention is { } retention)
            {
                if (string.IsNullOrWhiteSpace(retention.Regime) ||
                    string.IsNullOrWhiteSpace(retention.FloorClass) ||
                    retention.MinimumRetentionDays < 0)
                    throw Fail(definition, fieldName, "aspect.policy_invalid");
                if (retentionDays is not null && retention.MinimumRetentionDays < retentionDays)
                    throw Fail(definition, fieldName, "aspect.relax_forbidden");
                retentionDays = retention.MinimumRetentionDays;
            }

            if (grain.Lifecycle is { } lifecycle)
            {
                if (immutability is not null && (int)lifecycle.Immutability < (int)immutability.Value)
                    throw Fail(definition, fieldName, "aspect.relax_forbidden");
                immutability = lifecycle.Immutability;
            }

            if (grain.Lifecycle?.Residency is { } residency)
            {
                if (residency.AllowedJurisdictions.Any(string.IsNullOrWhiteSpace) ||
                    residency.ProhibitedJurisdictions?.Any(string.IsNullOrWhiteSpace) == true)
                    throw Fail(definition, fieldName, "aspect.policy_invalid");
                var declared = residency.AllowedJurisdictions.ToHashSet(StringComparer.OrdinalIgnoreCase);
                var effectiveAllowed = allowedResidency is null
                    ? declared
                    : allowedResidency.Intersect(declared, StringComparer.OrdinalIgnoreCase).ToHashSet(StringComparer.OrdinalIgnoreCase);
                foreach (var prohibited in residency.ProhibitedJurisdictions ?? []) prohibitedResidency.Add(prohibited);
                effectiveAllowed.ExceptWith(prohibitedResidency);
                if (effectiveAllowed.Count == 0)
                    throw Fail(definition, fieldName, "aspect.residency_unsatisfiable");
                allowedResidency = effectiveAllowed;
            }
        }
    }

    private static HashSet<RoleReference>? NarrowRoles(
        FormDefinition definition,
        string fieldName,
        HashSet<RoleReference>? inherited,
        IReadOnlyList<RoleReference>? declaredRoles)
    {
        if (declaredRoles is null) return inherited;
        var declared = declaredRoles.ToHashSet();
        if (declaredRoles.Any(role => string.IsNullOrWhiteSpace(role.Vocabulary) || string.IsNullOrWhiteSpace(role.Name)) || declared.Count != declaredRoles.Count)
            throw Fail(definition, fieldName, "aspect.policy_invalid");
        if (inherited is not null && !declared.IsSubsetOf(inherited))
            throw Fail(definition, fieldName, "aspect.relax_forbidden");
        return declared;
    }

    private static IEnumerable<AspectOverlay> EffectiveAspects(HarborlineOverlay overlay, string fieldName)
    {
        if (overlay.Aspects is not null) yield return overlay.Aspects;
        foreach (var section in overlay.Sections.Where(candidate => SectionContains(candidate, fieldName)))
        {
            if (section.Aspects is not null) yield return section.Aspects;
            foreach (var aspects in ItemAspects(section.Items, fieldName, [])) yield return aspects;
        }
        if (overlay.Fields[fieldName].Aspects is not null) yield return overlay.Fields[fieldName].Aspects!;
    }

    private static bool SectionContains(FormSection section, string fieldName) =>
        section.Fields.Contains(fieldName, StringComparer.Ordinal) || ItemContains(section.Items, fieldName);

    private static bool ItemContains(IReadOnlyList<FormItem>? items, string fieldName) =>
        items?.Any(item =>
            item.Kind == FormItemKind.Field && string.Equals(item.Key, fieldName, StringComparison.Ordinal) ||
            ItemContains(item.Items, fieldName)) == true;

    private static IEnumerable<AspectOverlay> ItemAspects(
        IReadOnlyList<FormItem>? items,
        string fieldName,
        IReadOnlyList<AspectOverlay> inherited)
    {
        foreach (var item in items ?? [])
        {
            var effective = item.Aspects is null ? inherited : inherited.Append(item.Aspects).ToArray();
            if (item.Kind == FormItemKind.Field && string.Equals(item.Key, fieldName, StringComparison.Ordinal))
                foreach (var aspects in effective) yield return aspects;
            foreach (var aspects in ItemAspects(item.Items, fieldName, effective)) yield return aspects;
        }
    }

    private static string TagKey(Tag tag) => $"{tag.System}\0{tag.Code}";

    private static FormDefinitionValidationException Fail(
        FormDefinition definition,
        string fieldName,
        string code) =>
        new(definition.Id, $"{code}: field '{fieldName}' failed publish policy admission.");
}

using Harborline.Foundation.Forms.Models;

namespace Harborline.Foundation.Forms.Engine.Authoring;

/// <summary>
/// The authoring-host boundary for admitting and publishing an immutable form-definition revision.
/// </summary>
public interface IFormDefinitionAuthoringPublisher
{
    /// <summary>
    /// Compiles every executable rule and page guard before the definition store is mutated, then
    /// registers and publishes the admitted draft revision.
    /// </summary>
    ValueTask<FormDefinition> RegisterAndPublishAsync(
        FormDefinition definition,
        CancellationToken cancellationToken = default);
}

using Harborline.Foundation.Assets.Common;

namespace Harborline.Foundation.Forms.Engine.Capabilities;

/// <summary>The coarse operations granted by a verified Forms bearer capability.</summary>
public enum FormCapabilityAction
{
    /// <summary>Render an existing or empty form view.</summary>
    Read,

    /// <summary>Validate or submit form work.</summary>
    Write,
}

/// <summary>
/// A verified capability. Roles are deliberately absent: authorization roles always come from
/// the current host-authenticated actor, never from bearer material.
/// </summary>
public sealed record VerifiedFormCapability(
    TenantId Tenant,
    string Subject,
    IReadOnlySet<FormCapabilityAction> Actions,
    DateTimeOffset ExpiresAt);

/// <summary>Supplies the request's Forms bearer without coupling Foundation to an HTTP stack.</summary>
public interface IFormCapabilityBearerProvider
{
    /// <summary>Returns the current request bearer, or <see langword="null"/> when absent.</summary>
    ValueTask<string?> GetBearerAsync(CancellationToken cancellationToken = default);
}

/// <summary>Resolves macaroon root-key bytes for one opaque location.</summary>
public interface IFormCapabilityRootKeyProvider
{
    /// <summary>Returns a root key or <see langword="null"/> for an unknown location.</summary>
    ValueTask<ReadOnlyMemory<byte>?> GetRootKeyAsync(
        string location,
        CancellationToken cancellationToken = default);
}

/// <summary>Verifies a source-compatible Forms macaroon and returns only trusted claims.</summary>
public interface IFormCapabilityVerifier
{
    /// <summary>
    /// Verifies encoding, signature, strict caveat shape, actions, and expiry. Every denial uses
    /// one opaque exception that never includes bearer, key, identifier, location, or caveat data.
    /// </summary>
    ValueTask<VerifiedFormCapability> VerifyAsync(
        string bearer,
        DateTimeOffset now,
        CancellationToken cancellationToken = default);
}

/// <summary>Mints source-compatible Forms macaroons for trusted host adapters.</summary>
public interface IFormCapabilityIssuer
{
    /// <summary>
    /// Issues a single-action capability. Embedded roles are retained only for wire compatibility.
    /// </summary>
    ValueTask<string> IssueAsync(
        TenantId tenant,
        string subject,
        IReadOnlyList<string> compatibilityRoles,
        IReadOnlyList<FormCapabilityAction> actions,
        DateTimeOffset expiresAt,
        CancellationToken cancellationToken = default);
}

/// <summary>Opaque fail-closed outcome for every capability verification denial.</summary>
public sealed class FormCapabilityDeniedException()
    : Exception("The form capability was denied.")
{
    /// <summary>Stable code safe for host-level mapping and telemetry.</summary>
    public string Code => "form.engine.denied";
}

using System.Globalization;
using System.Diagnostics.CodeAnalysis;
using System.Collections.Frozen;
using System.Security.Cryptography;
using System.Text;
using Harborline.Foundation.Assets.Common;

namespace Harborline.Foundation.Forms.Engine.Capabilities;

/// <summary>
/// Strict verifier for the pinned earlier source Forms macaroon wire format. It preserves the wire and
/// HMAC chain while closing ambiguous caveat and secret-echo behavior at the Harborline seam.
/// </summary>
public sealed class MacaroonFormCapabilityVerifier : IFormCapabilityVerifier
{
    private const string IdentifierVersion = "hlf1";
    private readonly IFormCapabilityRootKeyProvider _keys;

    /// <summary>Creates a verifier over a host-owned key provider.</summary>
    public MacaroonFormCapabilityVerifier(IFormCapabilityRootKeyProvider keys)
    {
        ArgumentNullException.ThrowIfNull(keys);
        _keys = keys;
    }

    /// <inheritdoc />
    public async ValueTask<VerifiedFormCapability> VerifyAsync(
        string bearer,
        DateTimeOffset now,
        CancellationToken cancellationToken = default)
    {
        try
        {
            cancellationToken.ThrowIfCancellationRequested();
            var macaroon = FormMacaroonCodec.Decode(bearer);
            var resolved = await _keys
                .GetRootKeyAsync(macaroon.Location, cancellationToken)
                .ConfigureAwait(false);
            if (resolved is null || resolved.Value.IsEmpty) Deny();

            var expected = FormMacaroonCodec.ComputeChain(
                resolved!.Value.Span,
                macaroon.Identifier,
                macaroon.Caveats);
            if (!CryptographicOperations.FixedTimeEquals(expected, macaroon.Signature)) Deny();

            var identifierAction = ParseIdentifierAction(macaroon.Identifier);
            var parsed = ParseCaveats(macaroon.Caveats);
            if (!parsed.Actions.Contains(identifierAction)) Deny();
            if (now > parsed.ExpiresAt) Deny();
            return new(parsed.Tenant, parsed.Subject, parsed.Actions, parsed.ExpiresAt);
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            throw;
        }
        catch (FormCapabilityDeniedException)
        {
            throw;
        }
        catch
        {
            throw new FormCapabilityDeniedException();
        }
    }

    private static ParsedCaveats ParseCaveats(IReadOnlyList<string> caveats)
    {
        TenantId? tenant = null;
        string? subject = null;
        DateTimeOffset? expiresAt = null;
        var actions = new HashSet<FormCapabilityAction>();

        foreach (var predicate in caveats)
        {
            if (string.IsNullOrWhiteSpace(predicate) || predicate.Length > FormMacaroonCodec.MaximumPartCharacters) Deny();
            var equals = predicate.IndexOf('=');
            if (equals <= 0 || equals == predicate.Length - 1) Deny();
            var key = predicate[..equals].Trim();
            var value = predicate[(equals + 1)..].Trim();
            if (key.Length == 0 || value.Length == 0) Deny();

            switch (key)
            {
                case "tenant":
                    if (tenant is not null) Deny();
                    tenant = new TenantId(value);
                    break;
                case "subject":
                    if (subject is not null) Deny();
                    subject = value;
                    break;
                case "expires":
                    if (expiresAt is not null) Deny();
                    if (!DateTimeOffset.TryParse(
                        value,
                        CultureInfo.InvariantCulture,
                        DateTimeStyles.RoundtripKind,
                        out var parsedExpiry)) Deny();
                    expiresAt = parsedExpiry;
                    break;
                case "role":
                    break;
                case "action":
                    if (actions.Count != 0) Deny();
                    var action = value switch
                    {
                        "read" => FormCapabilityAction.Read,
                        "write" => FormCapabilityAction.Write,
                        _ => throw new FormCapabilityDeniedException(),
                    };
                    actions.Add(action);
                    break;
                default:
                    Deny();
                    break;
            }
        }

        if (tenant is null || subject is null || expiresAt is null || actions.Count != 1) Deny();
        return new(tenant!.Value, subject!, actions.ToFrozenSet(), expiresAt!.Value);
    }

    private static FormCapabilityAction ParseIdentifierAction(string identifier)
    {
        var parts = identifier.Split(':');
        if (parts.Length != 3
            || !string.Equals(parts[0], IdentifierVersion, StringComparison.Ordinal)
            || parts[2].Length != 32
            || parts[2].Any(character => !Uri.IsHexDigit(character))) Deny();
        return parts[1] switch
        {
            "read" => FormCapabilityAction.Read,
            "write" => FormCapabilityAction.Write,
            _ => throw new FormCapabilityDeniedException(),
        };
    }

    [DoesNotReturn]
    private static void Deny() => throw new FormCapabilityDeniedException();

    private sealed record ParsedCaveats(
        TenantId Tenant,
        string Subject,
        IReadOnlySet<FormCapabilityAction> Actions,
        DateTimeOffset ExpiresAt);
}

/// <summary>Source-compatible Forms macaroon issuer over the narrowed root-key provider.</summary>
public sealed class MacaroonFormCapabilityIssuer : IFormCapabilityIssuer
{
    /// <summary>The pinned source location used for Forms capability root-key lookup.</summary>
    public const string DefaultLocation = "sunfish/forms";

    private readonly IFormCapabilityRootKeyProvider _keys;
    private readonly string _location;

    /// <summary>Creates an issuer over a host-owned key provider and optional location.</summary>
    public MacaroonFormCapabilityIssuer(
        IFormCapabilityRootKeyProvider keys,
        string location = DefaultLocation)
    {
        ArgumentNullException.ThrowIfNull(keys);
        ArgumentException.ThrowIfNullOrWhiteSpace(location);
        _keys = keys;
        _location = location;
    }

    /// <inheritdoc />
    public async ValueTask<string> IssueAsync(
        TenantId tenant,
        string subject,
        IReadOnlyList<string> compatibilityRoles,
        IReadOnlyList<FormCapabilityAction> actions,
        DateTimeOffset expiresAt,
        CancellationToken cancellationToken = default)
    {
        if (tenant.IsSystemSentinel) throw new ArgumentException("A concrete tenant is required.", nameof(tenant));
        ArgumentException.ThrowIfNullOrWhiteSpace(subject);
        ArgumentNullException.ThrowIfNull(compatibilityRoles);
        ArgumentNullException.ThrowIfNull(actions);
        if (actions.Count != 1) throw new ArgumentException("Exactly one action is required.", nameof(actions));

        if (compatibilityRoles.Any(string.IsNullOrWhiteSpace))
            throw new ArgumentException("Compatibility roles must be non-empty.", nameof(compatibilityRoles));
        if (actions.Any(action => !Enum.IsDefined(action)))
            throw new ArgumentException("Actions must be known.", nameof(actions));

        var caveats = new List<string>
        {
            $"tenant = {tenant.Value}",
            $"subject = {subject}",
            $"expires = {expiresAt.ToString("O", CultureInfo.InvariantCulture)}",
        };
        if (compatibilityRoles.Count > FormMacaroonCodec.MaximumCaveats - 4)
            throw new ArgumentException("Too many compatibility roles.", nameof(compatibilityRoles));
        caveats.AddRange(compatibilityRoles.Select(role => $"role = {role}"));
        caveats.AddRange(actions.Select(action => $"action = {ActionValue(action)}"));

        var actionValue = ActionValue(actions[0]);
        var identifier = $"hlf1:{actionValue}:{Guid.NewGuid():N}";
        FormMacaroonCodec.ValidateEncodable(_location, identifier, caveats);

        var key = await _keys.GetRootKeyAsync(_location, cancellationToken).ConfigureAwait(false);
        if (key is null || key.Value.IsEmpty)
            throw new InvalidOperationException("The Forms capability signing key is unavailable.");
        return FormMacaroonCodec.EncodeSigned(
            _location,
            identifier,
            caveats,
            key.Value.Span);
    }

    private static string ActionValue(FormCapabilityAction action) => action switch
    {
        FormCapabilityAction.Read => "read",
        FormCapabilityAction.Write => "write",
        _ => throw new ArgumentOutOfRangeException(nameof(action)),
    };
}

internal static class FormMacaroonCodec
{
    internal const int MaximumPartCharacters = 2048;
    internal const int MaximumEncodedCharacters = 32768;
    internal const int MaximumCaveats = 64;
    private const byte RecordSeparator = 0x1e;
    private const byte UnitSeparator = 0x1f;
    private static readonly UTF8Encoding StrictUtf8 = new(false, true);

    internal static FormMacaroon Decode(string bearer)
    {
        if (string.IsNullOrWhiteSpace(bearer)
            || bearer.Length > MaximumEncodedCharacters
            || bearer.Any(character => !IsBase64Url(character)))
            throw new FormCapabilityDeniedException();

        var remainder = bearer.Length % 4;
        if (remainder == 1) throw new FormCapabilityDeniedException();
        var normalized = bearer.Replace('-', '+').Replace('_', '/')
            + new string('=', remainder == 0 ? 0 : 4 - remainder);
        var bytes = Convert.FromBase64String(normalized);
        var unit = Array.IndexOf(bytes, UnitSeparator);
        if (unit < 0 || bytes.Length - unit - 1 != 32) throw new FormCapabilityDeniedException();

        var parts = Split(bytes.AsSpan(0, unit), RecordSeparator);
        if (parts.Count < 2 || parts.Count > MaximumCaveats + 2) throw new FormCapabilityDeniedException();
        var location = DecodePart(parts[0]);
        var identifier = DecodePart(parts[1]);
        if (string.IsNullOrWhiteSpace(location) || string.IsNullOrWhiteSpace(identifier))
            throw new FormCapabilityDeniedException();
        var caveats = parts.Skip(2).Select(DecodePart).ToArray();
        return new(location, identifier, caveats, bytes.AsSpan(unit + 1, 32).ToArray());
    }

    internal static string EncodeSigned(
        string location,
        string identifier,
        IReadOnlyList<string> caveats,
        ReadOnlySpan<byte> rootKey)
    {
        ValidateEncodable(location, identifier, caveats);
        var signature = ComputeChain(rootKey, identifier, caveats);
        return EncodeWithSignature(location, identifier, caveats, signature);
    }

    internal static string EncodeWithSignature(
        string location,
        string identifier,
        IReadOnlyList<string> caveats,
        ReadOnlySpan<byte> signature)
    {
        ValidateEncodable(location, identifier, caveats);
        if (signature.Length != 32) throw new ArgumentException("A 32-byte signature is required.", nameof(signature));
        var bytes = new List<byte>();
        Append(bytes, location);
        bytes.Add(RecordSeparator);
        Append(bytes, identifier);
        foreach (var caveat in caveats)
        {
            bytes.Add(RecordSeparator);
            Append(bytes, caveat);
        }
        bytes.Add(UnitSeparator);
        bytes.AddRange(signature.ToArray());
        var encoded = Convert.ToBase64String(bytes.ToArray()).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        if (encoded.Length > MaximumEncodedCharacters) throw new ArgumentException("The encoded capability is too large.", nameof(caveats));
        return encoded;
    }

    internal static void ValidateEncodable(
        string location,
        string identifier,
        IReadOnlyList<string> caveats)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(location);
        ArgumentException.ThrowIfNullOrWhiteSpace(identifier);
        ArgumentNullException.ThrowIfNull(caveats);
        if (caveats.Count > MaximumCaveats) throw new ArgumentException("Too many caveats.", nameof(caveats));
        ValidatePart(location, nameof(location));
        ValidatePart(identifier, nameof(identifier));
        foreach (var caveat in caveats) ValidatePart(caveat, nameof(caveats));
        var wireBytes = StrictUtf8.GetByteCount(location)
            + 1
            + StrictUtf8.GetByteCount(identifier)
            + caveats.Sum(caveat => 1 + StrictUtf8.GetByteCount(caveat))
            + 1
            + 32;
        if (((wireBytes + 2) / 3) * 4 > MaximumEncodedCharacters)
            throw new ArgumentException("The encoded capability is too large.", nameof(caveats));
    }

    internal static byte[] ComputeChain(
        ReadOnlySpan<byte> rootKey,
        string identifier,
        IReadOnlyList<string> caveats)
    {
        var signature = HMACSHA256.HashData(rootKey, StrictUtf8.GetBytes(identifier));
        foreach (var caveat in caveats)
            signature = HMACSHA256.HashData(signature, StrictUtf8.GetBytes(caveat));
        return signature;
    }

    private static bool IsBase64Url(char value) =>
        value is >= 'A' and <= 'Z'
        or >= 'a' and <= 'z'
        or >= '0' and <= '9'
        or '-' or '_';

    private static string DecodePart(byte[] value)
    {
        var result = StrictUtf8.GetString(value);
        if (result.Length > MaximumPartCharacters) throw new FormCapabilityDeniedException();
        return result;
    }

    private static void ValidatePart(string value, string parameterName)
    {
        if (value.Length > MaximumPartCharacters
            || value.IndexOf((char)RecordSeparator) >= 0
            || value.IndexOf((char)UnitSeparator) >= 0)
            throw new ArgumentException("Capability material exceeds the bounded wire format.", parameterName);
    }

    private static List<byte[]> Split(ReadOnlySpan<byte> source, byte delimiter)
    {
        var result = new List<byte[]>();
        var start = 0;
        for (var index = 0; index < source.Length; index++)
        {
            if (source[index] != delimiter) continue;
            result.Add(source[start..index].ToArray());
            start = index + 1;
        }
        result.Add(source[start..].ToArray());
        return result;
    }

    private static void Append(List<byte> target, string value) => target.AddRange(StrictUtf8.GetBytes(value));

    internal sealed record FormMacaroon(
        string Location,
        string Identifier,
        IReadOnlyList<string> Caveats,
        byte[] Signature);
}

using Harborline.Foundation.Authorization;
using Harborline.Foundation.Assets.Common;
using Harborline.Foundation.Forms.Engine.Capabilities;
using Harborline.Foundation.MultiTenancy;

namespace Harborline.Foundation.Forms.Engine;

/// <summary>
/// Resolves one current host actor, Party, and verified bearer capability into the Forms scope.
/// Bearer roles are never observed; current host-derived roles are snapshotted on every call.
/// </summary>
public sealed class CurrentFormExecutionContextProvider : IFormExecutionContextProvider
{
    private readonly IAuthenticatedActorContext _actor;
    private readonly IPrincipalPartyResolver _parties;
    private readonly IFormCapabilityBearerProvider _bearers;
    private readonly IFormCapabilityVerifier _capabilities;
    private readonly TimeProvider _clock;

    /// <summary>Creates the scoped production context provider.</summary>
    public CurrentFormExecutionContextProvider(
        IAuthenticatedActorContext actor,
        IPrincipalPartyResolver parties,
        IFormCapabilityBearerProvider bearers,
        IFormCapabilityVerifier capabilities,
        TimeProvider clock)
    {
        ArgumentNullException.ThrowIfNull(actor);
        ArgumentNullException.ThrowIfNull(parties);
        ArgumentNullException.ThrowIfNull(bearers);
        ArgumentNullException.ThrowIfNull(capabilities);
        _actor = actor;
        _parties = parties;
        _bearers = bearers;
        _capabilities = capabilities;
        _clock = clock ?? throw new ArgumentNullException(nameof(clock));
    }

    /// <inheritdoc />
    public async ValueTask<FormExecutionScope> GetRequiredAsync(
        FormEngineAction action,
        CancellationToken cancellationToken = default)
    {
        try
        {
            if (!Enum.IsDefined(action)) throw new FormEngineDeniedException();
            var before = Capture(_actor);
            var bearer = await _bearers.GetBearerAsync(cancellationToken).ConfigureAwait(false);
            if (string.IsNullOrWhiteSpace(bearer)) throw new FormEngineDeniedException();

            var capability = await _capabilities
                .VerifyAsync(bearer, _clock.GetUtcNow(), cancellationToken)
                .ConfigureAwait(false);
            if (capability.Tenant != before.Tenant
                || !string.Equals(capability.Subject, before.ActorId, StringComparison.Ordinal)
                || !capability.Actions.Contains(RequiredCapability(action)))
                throw new FormEngineDeniedException();

            var partyId = await _parties
                .ResolveAsync(before.ActorId, before.Tenant, cancellationToken)
                .ConfigureAwait(false);
            if (partyId is null || partyId == Guid.Empty) throw new FormEngineDeniedException();
            if (_clock.GetUtcNow() > capability.ExpiresAt) throw new FormEngineDeniedException();
            return new(before.Tenant, partyId.Value, before.ActorId, before.Roles);
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            throw;
        }
        catch (FormExecutionTenantUnavailableException)
        {
            throw;
        }
        catch (FormEngineDeniedException)
        {
            throw;
        }
        catch (FormCapabilityDeniedException)
        {
            throw new FormEngineDeniedException();
        }
        catch
        {
            throw new FormEngineDeniedException();
        }
    }

    private static ActorSnapshot Capture(IAuthenticatedActorContext actor)
    {
        var actorId = actor.UserId;
        var tenant = actor.Tenant;
        var currentRoles = actor.Roles;
        if (tenant is null || tenant.Id.IsSystemSentinel || tenant.Status != TenantStatus.Active)
            throw new FormExecutionTenantUnavailableException();
        if (string.IsNullOrWhiteSpace(actorId) || currentRoles is null)
            throw new FormEngineDeniedException();
        if (currentRoles.Any(string.IsNullOrWhiteSpace)) throw new FormEngineDeniedException();
        var roles = currentRoles
            .Where(role => !string.IsNullOrWhiteSpace(role))
            .Distinct(StringComparer.Ordinal)
            .ToArray();
        return new(tenant.Id, actorId, roles);
    }

    private static FormCapabilityAction RequiredCapability(FormEngineAction action) => action switch
    {
        FormEngineAction.Read => FormCapabilityAction.Read,
        FormEngineAction.Validate or FormEngineAction.Submit => FormCapabilityAction.Write,
        _ => throw new FormEngineDeniedException(),
    };

    private sealed record ActorSnapshot(TenantId Tenant, string ActorId, IReadOnlyList<string> Roles);
}

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Harborline.Foundation.Authorization;
using Harborline.Foundation.Forms.Engine.Authoring;
using Harborline.Foundation.Forms.Engine.Capabilities;
using Harborline.Foundation.Forms.Engine.Persistence;
using Harborline.Foundation.Forms.Engine.Projection;
using Harborline.Foundation.Forms.Engine.Security;

namespace Harborline.Foundation.Forms.Engine.DependencyInjection;

/// <summary>Selects the composition policy applied when registering Forms Engine services.</summary>
public enum FormEngineHostEnvironment
{
    /// <summary>Local development behavior.</summary>
    Development,
    /// <summary>Test-host behavior.</summary>
    Test,
    /// <summary>Production-host behavior with required attestations.</summary>
    Production
}

/// <summary>Registers Forms Engine services and its host-supplied infrastructure ports.</summary>
public static class FormEngineServiceCollectionExtensions
{
    private sealed class ProductionFieldSecurityAttestation;
    private sealed class CurrentRequestContextAttestation;
    private sealed class MacaroonCapabilityAttestation;

    private static readonly Type[] MandatoryProductionPorts =
    [
        typeof(IFormExecutionContextProvider),
        typeof(Harborline.Foundation.Forms.IFormDefinitionStore),
        typeof(Harborline.Foundation.Forms.IReuseResolver),
        typeof(Harborline.Kernel.SchemaValidation.ISchemaRegistry),
        typeof(IFormFieldSecurity),
        typeof(IFormFieldGovernanceResolver),
        typeof(IFormTenantProtectionKeyProvider),
        typeof(IFormDecryptCapabilityProvider),
        typeof(IFormSensitiveReadAudit),
        typeof(IFormSubmissionTransactionStore),
        typeof(IFormProjectionSink),
        typeof(TimeProvider),
    ];

    /// <summary>
    /// Registers the fail-closed authoring-host publication boundary. Hosts should depend on
    /// <see cref="IFormDefinitionAuthoringPublisher"/> instead of calling the definition store's
    /// register and publish methods directly.
    /// </summary>
    public static IServiceCollection AddHarborlineFormsAuthoringPublisher(this IServiceCollection services)
    {
        ArgumentNullException.ThrowIfNull(services);
        services.TryAddSingleton<IFormFieldGovernanceResolver, DefaultFormFieldGovernanceResolver>();
        services.TryAddSingleton<IFormDefinitionPolicyAdmission, DefaultFormDefinitionPolicyAdmission>();
        services.TryAddScoped<IFormDefinitionAuthoringPublisher, FormDefinitionAuthoringPublisher>();
        return services;
    }

    /// <summary>Registers the core Forms Engine graph and validates production-only composition requirements.</summary>
    public static IServiceCollection AddHarborlineFormsEngine(
        this IServiceCollection services,
        FormEngineHostEnvironment environment,
        Action<FormEngineOptions>? configure = null)
    {
        ArgumentNullException.ThrowIfNull(services);
        var options = new FormEngineOptions();
        configure?.Invoke(options);
        options.Validate();
        if (environment == FormEngineHostEnvironment.Production)
        {
            var usesCurrentRequestContext = services.Any(row => row.ServiceType == typeof(CurrentRequestContextAttestation))
                || services.Any(row => row.ServiceType == typeof(IFormExecutionContextProvider)
                    && row.ImplementationType == typeof(CurrentFormExecutionContextProvider));
            var usesMacaroonCapabilities = services.Any(row => row.ServiceType == typeof(MacaroonCapabilityAttestation))
                || services.Any(row => row.ServiceType == typeof(IFormCapabilityVerifier)
                    && row.ImplementationType == typeof(MacaroonFormCapabilityVerifier));
            var conditionalPorts = new List<Type>();
            if (usesCurrentRequestContext)
            {
                conditionalPorts.AddRange([
                    typeof(IAuthenticatedActorContext),
                    typeof(IPrincipalPartyResolver),
                    typeof(IFormCapabilityBearerProvider),
                    typeof(IFormCapabilityVerifier),
                ]);
            }
            if (usesMacaroonCapabilities) conditionalPorts.Add(typeof(IFormCapabilityRootKeyProvider));
            var missing = MandatoryProductionPorts.Concat(conditionalPorts).Distinct()
                .Where(type => !services.Any(row => row.ServiceType == type))
                .Select(type => type.Name)
                .ToArray();
            if (missing.Length > 0)
                throw new InvalidOperationException($"Forms Engine production composition is missing mandatory providers: {string.Join(", ", missing)}.");
            if (services.Count(row => row.ServiceType == typeof(TimeProvider)) != 1)
                throw new InvalidOperationException("Forms Engine production composition requires exactly one host-supplied TimeProvider.");
            var singletonRequestPorts = usesCurrentRequestContext ? new[]
            {
                typeof(IFormExecutionContextProvider),
                typeof(IAuthenticatedActorContext),
                typeof(IFormCapabilityBearerProvider),
            }.Where(type => services.Any(row => row.ServiceType == type && row.Lifetime == ServiceLifetime.Singleton))
             .Select(type => type.Name)
             .ToArray() : [];
            if (singletonRequestPorts.Length > 0)
                throw new InvalidOperationException($"Forms Engine request-bound providers cannot be singleton: {string.Join(", ", singletonRequestPorts)}.");
            if (!services.Any(row => row.ServiceType == typeof(ProductionFieldSecurityAttestation)))
                throw new InvalidOperationException("Forms Engine production composition requires an attested governance-enforcing field-security registration.");
        }
        services.TryAddSingleton(options);
        services.TryAddScoped<IFormEngine, FormEngine>();
        return services;
    }

    /// <summary>Registers tenant-bound field protection and its governance resolver.</summary>
    public static IServiceCollection AddHarborlineFormsEngineTenantBoundFieldSecurity(
        this IServiceCollection services,
        FormFieldSecurityOptions options)
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(options);
        ArgumentException.ThrowIfNullOrWhiteSpace(options.HostJurisdiction);
        if (services.Any(row => row.ServiceType == typeof(IFormFieldSecurity)))
            throw new InvalidOperationException("Forms Engine field security is already registered; production attestation cannot be layered over another adapter.");
        services.TryAddSingleton(options);
        services.TryAddSingleton<IFormFieldGovernanceResolver, DefaultFormFieldGovernanceResolver>();
        services.AddScoped<IFormFieldSecurity>(provider => new TenantBoundAesGcmFormFieldSecurity(
            provider.GetRequiredService<IFormTenantProtectionKeyProvider>(),
            provider.GetRequiredService<IFormDecryptCapabilityProvider>(),
            provider.GetRequiredService<IFormFieldGovernanceResolver>(),
            provider.GetRequiredService<FormFieldSecurityOptions>(),
            provider.GetRequiredService<TimeProvider>()));
        services.TryAddSingleton<ProductionFieldSecurityAttestation>();
        return services;
    }

    /// <summary>Registers the request-scoped execution-context adapter.</summary>
    public static IServiceCollection AddHarborlineFormsEngineCurrentRequestContext(
        this IServiceCollection services)
    {
        ArgumentNullException.ThrowIfNull(services);
        services.TryAddScoped<IFormExecutionContextProvider, CurrentFormExecutionContextProvider>();
        services.TryAddSingleton<CurrentRequestContextAttestation>();
        return services;
    }

    /// <summary>Registers macaroon capability verification and issuance services.</summary>
    public static IServiceCollection AddHarborlineFormsEngineMacaroonCapabilities(
        this IServiceCollection services)
    {
        ArgumentNullException.ThrowIfNull(services);
        services.TryAddScoped<IFormCapabilityVerifier, MacaroonFormCapabilityVerifier>();
        services.TryAddScoped<IFormCapabilityIssuer, MacaroonFormCapabilityIssuer>();
        services.TryAddSingleton<MacaroonCapabilityAttestation>();
        return services;
    }

    /// <summary>Registers the in-memory submission store for non-production environments.</summary>
    public static IServiceCollection AddHarborlineFormsEngineInMemorySubmissionStore(
        this IServiceCollection services,
        FormEngineHostEnvironment environment)
    {
        ArgumentNullException.ThrowIfNull(services);
        if (environment == FormEngineHostEnvironment.Production)
            throw new InvalidOperationException("The in-memory Forms Engine submission adapter is not permitted in Production.");
        services.TryAddSingleton<InMemoryFormSubmissionState>();
        services.TryAddSingleton<IFormSubmissionTransactionStore>(provider =>
            new InMemoryFormSubmissionStore(provider.GetRequiredService<InMemoryFormSubmissionState>()));
        return services;
    }

    /// <summary>Registers the configured single-process append-only journal submission store.</summary>
    public static IServiceCollection AddHarborlineFormsEngineFileSubmissionStore(
        this IServiceCollection services,
        Action<FileJournalFormSubmissionStoreOptions> configure)
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(configure);
        if (services.Any(row => row.ServiceType == typeof(IFormSubmissionTransactionStore)))
            throw new InvalidOperationException("A Forms Engine submission store is already registered.");
        var options = new FileJournalFormSubmissionStoreOptions();
        configure(options);
        options.Validate();
        services.AddSingleton(options);
        services.AddSingleton<IFormSubmissionTransactionStore, FileJournalFormSubmissionStore>();
        return services;
    }
}

using System.Globalization;
using System.Text.Json;
using System.Text.Json.Nodes;
using Harborline.Contracts.Authorization;
using Contract = Harborline.Contracts.Forms;
using State = Harborline.Foundation.Forms.Models;
using Harborline.Foundation.RuleEngine;
using Harborline.Foundation.RuleEngine.Compilation;
using Harborline.Foundation.RuleEngine.Context;
using Harborline.Foundation.RuleEngine.Graph;
using Harborline.Foundation.RuleEngine.Model;
using Harborline.Foundation.RuleEngine.Environments;
using Harborline.Kernel.SchemaValidation;

namespace Harborline.Foundation.Forms.Engine;

internal sealed record FormCandidateEvaluation(
    JsonDocument AcceptedCandidate,
    IReadOnlyList<Contract.ValidationError> Errors,
    IReadOnlySet<string> HiddenFields,
    IReadOnlySet<string> ReadOnlyFields,
    RuleEvaluationResult? Rules) : IDisposable
{
    /// <inheritdoc />
    public void Dispose() => AcceptedCandidate.Dispose();
}

internal static class FormCandidateEvaluator
{
    /// <summary>Evaluates a candidate against the supplied form definition and validation limits.</summary>
    public static ValueTask<FormCandidateEvaluation> EvaluateAsync(
        FormExecutionScope scope,
        State.FormDefinition definition,
        JsonDocument candidate,
        ISchemaRegistry schemas,
        int maximumCandidateBytes,
        TimeProvider clock,
        CancellationToken cancellationToken) =>
        EvaluateAsync(scope, definition, candidate, schemas, maximumCandidateBytes, clock.GetUtcNow(), cancellationToken);

    /// <summary>Evaluates a candidate with the provided schema, byte limit, and evaluation timestamp.</summary>
    public static async ValueTask<FormCandidateEvaluation> EvaluateAsync(
        FormExecutionScope scope,
        State.FormDefinition definition,
        JsonDocument candidate,
        ISchemaRegistry schemas,
        int maximumCandidateBytes,
        DateTimeOffset instant,
        CancellationToken cancellationToken)
    {
        var bytes = JsonSerializer.SerializeToUtf8Bytes(candidate.RootElement);
        if (bytes.Length > maximumCandidateBytes)
            return Invalid(candidate, Error(
                "",
                "Candidate exceeds the configured byte ceiling.",
                Contract.ValidationErrorKind.ResourceBound,
                "candidate-too-large",
                new Dictionary<string, string>
                {
                    ["limit"] = maximumCandidateBytes.ToString(CultureInfo.InvariantCulture),
                    ["bytes"] = bytes.Length.ToString(CultureInfo.InvariantCulture),
                }));
        if (candidate.RootElement.ValueKind != JsonValueKind.Object)
            return Invalid(candidate, Error("", "Candidate must be a JSON object.", Contract.ValidationErrorKind.Schema, "type"));

        var objectNode = JsonNode.Parse(candidate.RootElement.GetRawText())!.AsObject();
        var clock = new PinnedClock(instant);
        var errors = new List<Contract.ValidationError>();
        var hidden = new HashSet<string>(StringComparer.Ordinal);
        var readOnly = new HashSet<string>(StringComparer.Ordinal);

        ApplyWriteAuthorization(scope, definition, objectNode, errors);

        // Materialise computed values before page guards read the candidate, then keep pruning
        // monotonic. A validation result from the raw submission must never authorize a different
        // document, and the final candidate is evaluated exactly once for diagnostics.
        RuleEvaluationResult? rules;
        while (true)
        {
            rules = EvaluateRules(definition, objectNode, clock, cancellationToken);
            ApplyRuleProjection(definition, objectNode, rules, hidden, readOnly, errors, materializeValues: true, includeValueErrors: false, includeValidation: false, clock, cancellationToken);
            var removed = false;
            foreach (var key in hidden) removed |= objectNode.Remove(key);
            if (!removed) break;
        }
        rules = EvaluateRules(definition, objectNode, clock, cancellationToken);
        ApplyRuleProjection(definition, objectNode, rules, hidden, readOnly, errors, materializeValues: true, includeValueErrors: true, includeValidation: true, clock, cancellationToken);

        var acceptedBytes = JsonSerializer.SerializeToUtf8Bytes(objectNode);
        SchemaValidationResult schemaResult;
        try
        {
            schemaResult = await schemas.ValidateAsync(new SchemaId(definition.SchemaRef.Value), acceptedBytes, cancellationToken).ConfigureAwait(false);
        }
        catch (SchemaNotFoundException)
        {
            errors.Add(Error("", "The form schema was not found.", Contract.ValidationErrorKind.NotFound, "form.engine.not-found"));
            schemaResult = new(false, Array.Empty<SchemaValidationError>());
        }

        errors.AddRange(schemaResult.Errors
            .Where(row => !TargetsPrunedField(row.JsonPointer, hidden, readOnly))
            .Select(row => Error(row.JsonPointer, row.Message, Contract.ValidationErrorKind.Schema, row.Code, row.Params)));
        return new(JsonDocument.Parse(acceptedBytes), errors, hidden, readOnly, rules);
    }

    private static void ApplyWriteAuthorization(
        FormExecutionScope scope,
        State.FormDefinition definition,
        JsonObject candidate,
        List<Contract.ValidationError> errors)
    {
        foreach (var section in definition.Overlay.Sections)
        {
            var sectionWritable = HasAnyRole(scope, section.Access.WriteRoles);
            foreach (var fieldName in EnumerateFieldNames(section))
            {
                if (!candidate.ContainsKey(fieldName) || !definition.Overlay.Fields.TryGetValue(fieldName, out var field)) continue;
                var fieldWritable = field.FieldWriteRoles is null || HasAnyRole(scope, field.FieldWriteRoles);
                if (!sectionWritable || !fieldWritable)
                    errors.Add(Error($"/{EscapePointer(fieldName)}", "The field is not writable.", Contract.ValidationErrorKind.Authorization, "form.engine.denied"));
            }
        }
    }

    private static RuleEvaluationResult? EvaluateRules(
        State.FormDefinition definition,
        JsonObject candidate,
        TimeProvider clock,
        CancellationToken cancellationToken)
    {
        if (definition.Overlay.Rules.Count == 0) return null;
        var compiled = RuleCompiler.Compile(definition.Overlay.Rules.Select(FormContractMapper.ToContractRule).ToArray());
        if (compiled.RuleCount == 0) return null;
        return new FormRuleGraph(compiled, clock, FormsExpressionEnvironment.Admitted.For(EvaluationPhase.Submission)).EvaluateInstance(RuleInstance.FromJson(candidate), cancellationToken);
    }

    private static HashSet<string> ApplyRuleProjection(
        State.FormDefinition definition,
        JsonObject candidate,
        RuleEvaluationResult? result,
        HashSet<string> hidden,
        HashSet<string> readOnly,
        List<Contract.ValidationError> errors,
        bool materializeValues,
        bool includeValueErrors,
        bool includeValidation,
        TimeProvider clock,
        CancellationToken cancellationToken)
    {
        var hiddenPages = new HashSet<string>(StringComparer.Ordinal);
        var hiddenSections = new HashSet<string>(StringComparer.Ordinal);
        if (result is null)
        {
            EvaluatePageGuards(definition, candidate, hiddenPages, hiddenSections, clock, FormsExpressionEnvironment.Admitted.For(EvaluationPhase.Submission), cancellationToken);
            ExpandHiddenSections(definition, hiddenSections, hidden);
            return hiddenPages;
        }
        foreach (var (target, state) in result.Visibility)
        {
            if (target.StartsWith("field:", StringComparison.Ordinal))
            {
                var field = target["field:".Length..];
                if (!state.Visible) hidden.Add(field);
                if (state.ReadOnly) readOnly.Add(field);
            }
            else if (target.StartsWith("section:", StringComparison.Ordinal) && !state.Visible)
                hiddenSections.Add(target["section:".Length..]);
        }

        ExpandHiddenSections(definition, hiddenSections, hidden);

        if (materializeValues)
        {
            foreach (var (target, computed) in result.Values)
            {
                if (!target.StartsWith("field:", StringComparison.Ordinal)) continue;
                var field = target["field:".Length..];
                if (hidden.Contains(field)) continue;
                if (computed.State == ValueState.Resolved) candidate[field] = computed.Value?.DeepClone();
                else if (includeValueErrors) errors.Add(Error($"/{EscapePointer(field)}", "A calculated value could not be resolved.", Contract.ValidationErrorKind.Schema, computed.Error?.Code ?? "rule.unresolved", computed.Error?.Params));
            }
        }

        EvaluatePageGuards(definition, candidate, hiddenPages, hiddenSections, clock, FormsExpressionEnvironment.Admitted.For(EvaluationPhase.Submission), cancellationToken);
        ExpandHiddenSections(definition, hiddenSections, hidden);

        if (!includeValidation) return hiddenPages;

        foreach (var (target, state) in result.Visibility)
        {
            if (!target.StartsWith("field:", StringComparison.Ordinal)) continue;
            var field = target["field:".Length..];
            if (state.Required && state.Visible && !state.ReadOnly && IsEmpty(candidate, field))
                errors.Add(Error($"/{EscapePointer(field)}", "The field is required.", Contract.ValidationErrorKind.Schema, "required", new Dictionary<string, string> { ["field"] = field }));
        }

        foreach (var outcome in result.Validations)
        {
            if (outcome.Validity is not { Ok: false } validity) continue;
            var pointer = TargetPointer(outcome.Target.Key);
            if (pointer.Length > 1 && hidden.Contains(pointer[1..])) continue;
            if (pointer.Length == 0) pointer = MissingReferencedFieldPointer(definition, outcome.RuleId, candidate);
            var boundPages = definition.Overlay.Pages?.Where(page => page.Checks?.Contains(outcome.RuleId, StringComparer.Ordinal) == true).ToArray() ?? [];
            var onlyHiddenPageCheck = boundPages.Length > 0 && boundPages.All(page => hiddenPages.Contains(page.Id));
            if (onlyHiddenPageCheck) continue;
            errors.Add(Error(pointer, "A form rule failed.", Contract.ValidationErrorKind.Schema, validity.Error?.Code ?? outcome.RuleId, validity.Error?.Params));
        }
        if (result.HasPending)
            errors.Add(Error("", "A calculated value is pending.", Contract.ValidationErrorKind.ResourceBound, "rule.pending"));
        return hiddenPages;
    }

    private static string MissingReferencedFieldPointer(State.FormDefinition definition, string ruleId, JsonObject candidate)
    {
        var rule = definition.Overlay.Rules.FirstOrDefault(row => string.Equals(row.Id, ruleId, StringComparison.Ordinal));
        if (rule is null) return "";
        JsonNode? expression;
        try { expression = JsonNode.Parse(rule.Expression); }
        catch (JsonException) { return ""; }
        var field = ReferencedFields(expression).FirstOrDefault(name => !candidate.ContainsKey(name));
        return field is null ? "" : "/" + EscapePointer(field);
    }

    private static IEnumerable<string> ReferencedFields(JsonNode? node)
    {
        switch (node)
        {
            case JsonObject obj when obj.TryGetPropertyValue("var", out var variable):
            {
                var path = variable switch
                {
                    JsonValue value when value.TryGetValue<string>(out var text) => text,
                    JsonArray { Count: > 0 } array when array[0] is JsonValue value && value.TryGetValue<string>(out var text) => text,
                    _ => null,
                };
                var field = path switch
                {
                    null or "" or "self" => null,
                    _ when path.StartsWith("field.", StringComparison.Ordinal) => path["field.".Length..],
                    _ when path.StartsWith("parent.", StringComparison.Ordinal) => path["parent.".Length..],
                    _ when path.StartsWith("section.", StringComparison.Ordinal) && path["section.".Length..].IndexOf('.', StringComparison.Ordinal) is var dot and >= 0
                        => path[("section.".Length + dot + 1)..],
                    _ when path.StartsWith("row.", StringComparison.Ordinal) || path.StartsWith("table.", StringComparison.Ordinal) => null,
                    _ => path,
                };
                if (field is not null) yield return field;
                foreach (var child in obj.Select(row => row.Value))
                    foreach (var nested in ReferencedFields(child)) yield return nested;
                break;
            }
            case JsonObject obj:
                foreach (var child in obj.Select(row => row.Value))
                    foreach (var nested in ReferencedFields(child)) yield return nested;
                break;
            case JsonArray array:
                foreach (var child in array)
                    foreach (var nested in ReferencedFields(child)) yield return nested;
                break;
        }
    }

    private static void ExpandHiddenSections(
        State.FormDefinition definition,
        IReadOnlySet<string> hiddenSections,
        HashSet<string> hidden)
    {
        foreach (var section in definition.Overlay.Sections.Where(row => hiddenSections.Contains(row.Id)))
        {
            foreach (var field in EnumerateFieldNames(section)) hidden.Add(field);
            foreach (var item in section.Items ?? Array.Empty<State.FormItem>())
                if (item.Kind != State.FormItemKind.Field) hidden.Add(item.Key);
        }
    }

    private static void EvaluatePageGuards(
        State.FormDefinition definition,
        JsonObject candidate,
        HashSet<string> hiddenPages,
        HashSet<string> hiddenSections,
        TimeProvider clock,
        EvaluationAdmission admission,
        CancellationToken cancellationToken)
    {
        if (definition.Overlay.Pages is not { Count: > 0 }) return;
        var context = candidate.ToDictionary(row => row.Key, row => row.Value?.DeepClone(), StringComparer.Ordinal);
        var evaluator = new GuardEvaluator(clock: clock);
        foreach (var page in definition.Overlay.Pages.Where(row => row.VisibleWhen is not null))
        {
            var guard = new Contract.RuleDefinition
            {
                Id = $"page-guard:{page.Id}", Tier = Contract.RuleTier.JsonLogic, Scope = Contract.RuleScope.Schema,
                ScopeTarget = "", Expression = page.VisibleWhen!, Action = Contract.RuleActionKind.Validate,
            };
            if (evaluator.EvaluateGuard(guard, RuleContextSnapshot.Capture(context), RuleEvalScope.Root, admission, cancellationToken).Ok) continue;
            hiddenPages.Add(page.Id);
            foreach (var section in page.Sections) hiddenSections.Add(section);
        }
    }

    /// <summary>
    /// The pages the render path hides (forms-eng-4): each page guard is evaluated through Rules
    /// over the rendered candidate with resolved computed values materialised first, as submit does.
    /// </summary>
    internal static IReadOnlySet<string> HiddenPages(
        State.FormDefinition definition,
        JsonDocument candidate,
        RuleEvaluationResult? rules,
        DateTimeOffset instant,
        CancellationToken cancellationToken)
    {
        var hiddenPages = new HashSet<string>(StringComparer.Ordinal);
        if (definition.Overlay.Pages is not { Count: > 0 } || candidate.RootElement.ValueKind != JsonValueKind.Object) return hiddenPages;
        var node = JsonNode.Parse(candidate.RootElement.GetRawText())!.AsObject();
        foreach (var (target, computed) in rules?.Values ?? new Dictionary<string, ComputedValue>())
            if (target.StartsWith("field:", StringComparison.Ordinal) && computed.State == ValueState.Resolved)
                node[target["field:".Length..]] = computed.Value?.DeepClone();
        EvaluatePageGuards(definition, node, hiddenPages, new HashSet<string>(StringComparer.Ordinal), new PinnedClock(instant), FormsExpressionEnvironment.Admitted.For(EvaluationPhase.Render), cancellationToken);
        return hiddenPages;
    }

    internal static IReadOnlySet<string> ReadableFields(FormExecutionScope scope, State.FormDefinition definition)
    {
        var result = new HashSet<string>(StringComparer.Ordinal);
        foreach (var section in definition.Overlay.Sections)
        {
            if (!HasAnyRole(scope, section.Access.ReadRoles)) continue;
            foreach (var fieldName in EnumerateFieldNames(section))
            {
                if (!definition.Overlay.Fields.TryGetValue(fieldName, out var field)) continue;
                if (field.FieldReadRoles is null || HasAnyRole(scope, field.FieldReadRoles)) result.Add(fieldName);
            }
        }
        return result;
    }

    internal static bool HasAnyRole(FormExecutionScope scope, IReadOnlyList<RoleReference> required) =>
        required.Count == 0
        || scope.RoleVocabulary is not null
        && scope.HeldRoles is not null
        && RoleGateResolver.Allows(new RoleGate(required), scope.RoleVocabulary, scope.HeldRoles);

    internal static IEnumerable<string> EnumerateFieldNames(State.FormSection section) =>
        section.Fields.Concat(section.Items is null ? [] : EnumerateItems(section.Items)).Distinct(StringComparer.Ordinal);

    private static IEnumerable<string> EnumerateItems(IEnumerable<State.FormItem> items)
    {
        foreach (var item in items)
        {
            if (item.Kind == State.FormItemKind.Field) yield return item.Key;
            if (item.Items is not null)
                foreach (var child in EnumerateItems(item.Items)) yield return child;
        }
    }

    private static FormCandidateEvaluation Invalid(JsonDocument candidate, params Contract.ValidationError[] errors) =>
        new(JsonDocument.Parse(candidate.RootElement.GetRawText()), errors, new HashSet<string>(), new HashSet<string>(), null);

    private static Contract.ValidationError Error(
        string pointer,
        string message,
        Contract.ValidationErrorKind kind,
        string? code,
        IReadOnlyDictionary<string, string>? parameters = null) => new()
        {
            JsonPointer = pointer,
            Message = message,
            Kind = kind,
            Code = code is null ? default : Contract.Optional<string>.Some(code),
            Params = parameters is null ? default : Contract.Optional<IReadOnlyDictionary<string, string>>.Some(parameters),
        };

    private static bool IsEmpty(JsonObject candidate, string field) =>
        !candidate.TryGetPropertyValue(field, out var node)
        || node is null
        || node is JsonValue value && value.TryGetValue<string>(out var text) && text.Length == 0
        || node is JsonArray array && array.Count == 0;

    private sealed class PinnedClock(DateTimeOffset instant) : TimeProvider
    {
        /// <inheritdoc />
        public override DateTimeOffset GetUtcNow() => instant;
    }

    private static bool TargetsPrunedField(string pointer, IReadOnlySet<string> hidden, IReadOnlySet<string> readOnly)
    {
        if (!pointer.StartsWith("/", StringComparison.Ordinal)) return false;
        var segment = pointer[1..].Split('/', 2)[0].Replace("~1", "/", StringComparison.Ordinal).Replace("~0", "~", StringComparison.Ordinal);
        return hidden.Contains(segment) || readOnly.Contains(segment);
    }

    private static string TargetPointer(string target)
    {
        if (target.StartsWith("field:", StringComparison.Ordinal)) return "/" + EscapePointer(target["field:".Length..]);
        if (target.StartsWith("row:", StringComparison.Ordinal)) return "/" + target["row:".Length..];
        if (target.StartsWith("agg:", StringComparison.Ordinal))
        {
            var value = target["agg:".Length..];
            var slash = value.IndexOf('/');
            return slash < 0 ? "" : "/" + EscapePointer(value[..slash]);
        }
        return "";
    }

    private static string EscapePointer(string value) => value.Replace("~", "~0", StringComparison.Ordinal).Replace("/", "~1", StringComparison.Ordinal);
}

using System.Text.Json;
using Contract = Harborline.Contracts.Forms;
using State = Harborline.Foundation.Forms.Models;
using Harborline.Foundation.RuleEngine;
using Harborline.Foundation.RuleEngine.Model;

namespace Harborline.Foundation.Forms.Engine;

internal static class FormContractMapper
{
    /// <summary>Converts an internal rule definition into its public contract representation.</summary>
    public static Contract.RuleDefinition ToContractRule(State.RuleDefinition rule) => new()
    {
        Id = rule.Id,
        Tier = rule.Tier switch { State.RuleTier.JsonSchema => Contract.RuleTier.JsonSchema, State.RuleTier.JsonLogic => Contract.RuleTier.JsonLogic, _ => Contract.RuleTier.PowerFx },
        Scope = rule.Scope switch { State.RuleScope.Field => Contract.RuleScope.Field, State.RuleScope.Section => Contract.RuleScope.Section, State.RuleScope.Schema => Contract.RuleScope.Schema, State.RuleScope.Row => Contract.RuleScope.Row, _ => Contract.RuleScope.Table },
        ScopeTarget = rule.ScopeTarget,
        Expression = rule.Expression,
        Action = rule.Action switch
        {
            State.RuleActionKind.Visibility => Contract.RuleActionKind.Visibility,
            State.RuleActionKind.Required => Contract.RuleActionKind.Required,
            State.RuleActionKind.ReadOnly => Contract.RuleActionKind.ReadOnly,
            State.RuleActionKind.Validate => Contract.RuleActionKind.Validate,
            State.RuleActionKind.Compute => Contract.RuleActionKind.Compute,
            State.RuleActionKind.Presentation => Contract.RuleActionKind.Presentation,
            _ => Contract.RuleActionKind.Options,
        },
        ErrorMessage = rule.ErrorMessage is null ? default : ToText(rule.ErrorMessage),
        Presentation = rule.Presentation is null ? default : new Contract.PresentationHint
        {
            Severity = rule.Presentation.Severity switch
            {
                "info" => Contract.PresentationHintSeverityValue.Info,
                "warn" => Contract.PresentationHintSeverityValue.Warn,
                "error" => Contract.PresentationHintSeverityValue.Error,
                _ => default(Contract.Optional<Contract.PresentationHintSeverityValue>),
            },
            Badge = rule.Presentation.Badge is null ? default : ToText(rule.Presentation.Badge),
            StyleToken = rule.Presentation.StyleToken is null ? default : rule.Presentation.StyleToken,
        },
    };

    /// <summary>Builds a public form view from the effective definition and readable candidate projection.</summary>
    public static Contract.FormView ToView(
        FormExecutionScope scope,
        State.FormDefinition definition,
        JsonDocument? candidate,
        IReadOnlySet<string> sensitiveFields,
        IReadOnlySet<string> withheldFields,
        RuleEvaluationResult? rules,
        IReadOnlyDictionary<string, FormBoundField>? bindings,
        IReadOnlySet<string> hiddenPages)
    {
        var readable = FormCandidateEvaluator.ReadableFields(scope, definition);
        var projected = new Dictionary<string, Contract.FormViewField>(StringComparer.Ordinal);
        foreach (var (name, field) in definition.Overlay.Fields)
        {
            var binding = bindings?.GetValueOrDefault(name);
            var isReadable = readable.Contains(name) && !withheldFields.Contains(name) && binding?.Readable != false;
            var ruleState = rules?.Visibility.GetValueOrDefault($"field:{name}");
            var presentation = RulePresentationFor(name, rules);
            var value = isReadable && candidate?.RootElement.TryGetProperty(name, out var element) == true
                ? Contract.Optional<JsonElement>.Some(element.Clone())
                : default;
            projected[name] = new Contract.FormViewField
            {
                Name = name,
                Label = ToText(field.Label),
                HelpText = field.HelpText is null ? default : Contract.Optional<Contract.InternationalizedText?>.Some(ToText(field.HelpText)),
                ControlHint = isReadable && binding?.Constraints.Editor is { } editor ? Contract.Optional<string?>.Some(editor.ToString()) : default,
                PermittedValues = isReadable && binding?.Constraints.Values is { } values ? Contract.Optional<IReadOnlyList<string>>.Some(values) : default,
                IsSensitive = sensitiveFields.Contains(name) || field.PiiSensitivity == State.PiiSensitivity.Sensitive,
                IsReadable = isReadable,
                Value = value,
                ReadOnly = ruleState is null ? default : ruleState.ReadOnly,
                Presentation = ToPresentation(presentation),
                Rules = RulesFor(name, rules, ruleState, presentation),
            };
        }

        var sections = definition.Overlay.Sections.Select(section => new Contract.FormViewSection
        {
            Id = section.Id,
            Title = ToText(section.Title),
            Fields = section.Fields.Where(projected.ContainsKey).Select(name => projected[name]).ToArray(),
            Layout = section.Layout is null
                ? default(Contract.Optional<Contract.SectionLayout>)
                : ToLayout(section.Layout),
            FieldPlacement = section.FieldPlacement is null
                ? default(Contract.Optional<IReadOnlyDictionary<string, Contract.FieldPlacement>>)
                : section.FieldPlacement.ToDictionary(row => row.Key, row => ToPlacement(row.Value), StringComparer.Ordinal),
            Items = section.Items is null ? default : Contract.Optional<IReadOnlyList<Contract.FormViewItem>>.Some(ToItems(section.Items, projected)),
        }).ToArray();

        return new Contract.FormView
        {
            FormId = definition.Id.Value,
            Version = definition.Version.ToString(),
            Title = definition.Overlay.Title is null ? default : Contract.Optional<Contract.InternationalizedText?>.Some(ToText(definition.Overlay.Title)),
            Description = definition.Overlay.Description is null ? default : Contract.Optional<Contract.InternationalizedText?>.Some(ToText(definition.Overlay.Description)),
            Sections = sections,
            Pages = definition.Overlay.Pages is { Count: > 0 } pages
                ? pages.Select(page => new Contract.FormViewPage
                {
                    Id = page.Id,
                    Title = ToText(page.Title),
                    Sections = page.Sections.ToArray(),
                    Visible = !hiddenPages.Contains(page.Id),
                }).ToArray()
                : default(Contract.Optional<IReadOnlyList<Contract.FormViewPage>>),
        };
    }

    /// <summary>Converts localized internal text into the public contract shape.</summary>
    public static Contract.InternationalizedText ToText(State.InternationalizedText text) => new()
    {
        DefaultLocale = text.DefaultLocale,
        Values = new Dictionary<string, string>(text.Values, StringComparer.Ordinal),
    };

    private static PresentationOutcome? RulePresentationFor(string field, RuleEvaluationResult? rules)
    {
        return rules?.ByRule.Values.LastOrDefault(
            row => row.Target.Key == $"field:{field}" && row.Presentation is not null)?.Presentation;
    }

    private static Contract.Optional<Contract.PresentationOutcome> ToPresentation(PresentationOutcome? outcome)
    {
        if (outcome is null) return default;
        return new Contract.PresentationOutcome
        {
            Severity = outcome.Severity is null ? default : Contract.Optional<Contract.Severity?>.Some(outcome.Severity.Value switch
            {
                Severity.Info => Contract.Severity.Info,
                Severity.Warn => Contract.Severity.Warn,
                _ => Contract.Severity.Error,
            }),
            Badge = outcome.Badge is null ? default : outcome.Badge,
            StyleToken = outcome.StyleToken is null ? default : outcome.StyleToken,
        };
    }

    private static Contract.Optional<Contract.FormViewFieldRules> RulesFor(
        string field,
        RuleEvaluationResult? rules,
        VisibilityState? visibility,
        PresentationOutcome? presentation)
    {
        if (rules is null) return default;
        var hasComputed = rules.Values.TryGetValue($"field:{field}", out var computed);
        if (visibility is null && !hasComputed && presentation is null) return default;
        return new Contract.FormViewFieldRules
        {
            Visible = visibility?.Visible ?? true,
            Required = visibility?.Required ?? false,
            ReadOnly = visibility?.ReadOnly ?? false,
            Computed = computed is { State: ValueState.Resolved }
                ? Contract.Optional<JsonElement>.Some(JsonSerializer.SerializeToElement(computed.Value))
                : default,
            PresentationSeverity = presentation?.Severity is null
                ? default
                : Contract.Optional<Contract.Severity?>.Some(presentation.Severity.Value switch
                {
                    Severity.Info => Contract.Severity.Info,
                    Severity.Warn => Contract.Severity.Warn,
                    _ => Contract.Severity.Error,
                }),
            PresentationBadge = presentation?.Badge is null ? default : presentation.Badge,
            PresentationStyleToken = presentation?.StyleToken is null ? default : presentation.StyleToken,
        };
    }

    private static Contract.SectionLayout ToLayout(State.SectionLayout layout) => new()
    {
        Kind = layout.Kind switch { State.SectionLayoutKind.Stack => Contract.SectionLayoutKind.Stack, State.SectionLayoutKind.Flex => Contract.SectionLayoutKind.Flex, _ => Contract.SectionLayoutKind.Grid },
        Direction = layout.Direction == State.FlexDirection.Row ? Contract.FlexDirection.Row : Contract.FlexDirection.Column,
        Wrap = layout.Wrap == State.FlexWrap.Wrap ? Contract.FlexWrap.Wrap : Contract.FlexWrap.Nowrap,
        Columns = layout.Columns,
        Gap = new Contract.LayoutGap(layout.Gap),
        CollapseBelow = layout.CollapseBelow switch { "sm" => Contract.LayoutBreakpoint.Sm, "md" => Contract.LayoutBreakpoint.Md, "lg" => Contract.LayoutBreakpoint.Lg, _ => default(Contract.Optional<Contract.LayoutBreakpoint>) },
        Density = layout.Density switch { "comfortable" => Contract.LayoutDensity.Comfortable, "compact" => Contract.LayoutDensity.Compact, _ => default(Contract.Optional<Contract.LayoutDensity>) },
        Align = ToAlign(layout.Align),
    };

    private static Contract.FieldPlacement ToPlacement(State.FieldPlacement placement) => new()
    {
        ColSpan = placement.ColSpan,
        Grow = placement.Grow,
        Width = ToWidth(placement.Width),
        Align = ToAlign(placement.Align),
    };

    private static Contract.Optional<Contract.LayoutAlign> ToAlign(string? value) => value switch
    {
        "start" => Contract.LayoutAlign.Start,
        "center" => Contract.LayoutAlign.Center,
        "end" => Contract.LayoutAlign.End,
        "stretch" => Contract.LayoutAlign.Stretch,
        _ => default,
    };

    private static IReadOnlyList<Contract.FormViewItem> ToItems(
        IReadOnlyList<State.FormItem> items,
        IReadOnlyDictionary<string, Contract.FormViewField> fields)
    {
        var result = new List<Contract.FormViewItem>();
        foreach (var item in items)
        {
            switch (item.Kind)
            {
                case State.FormItemKind.Field when fields.TryGetValue(item.Key, out var field):
                    result.Add(new Contract.FieldFormViewItem { Key = item.Key, Field = field });
                    break;
                case State.FormItemKind.Group:
                    result.Add(new Contract.GroupFormViewItem
                    {
                        Key = item.Key, Items = ToItems(item.Items ?? Array.Empty<State.FormItem>(), fields),
                        Title = item.Title is null ? default : ToText(item.Title),
                        Layout = item.Layout is null
                            ? default(Contract.Optional<Contract.SectionLayout>)
                            : ToLayout(item.Layout),
                        Placement = item.Placement is null
                            ? default(Contract.Optional<IReadOnlyDictionary<string, Contract.FieldPlacement>>)
                            : item.Placement.ToDictionary(row => row.Key, row => ToPlacement(row.Value), StringComparer.Ordinal),
                    });
                    break;
                case State.FormItemKind.Collection:
                    result.Add(new Contract.CollectionFormViewItem
                    {
                        Key = item.Key, Items = ToItems(item.Items ?? Array.Empty<State.FormItem>(), fields),
                        Title = item.Title is null ? default : ToText(item.Title),
                        Cardinality = item.Cardinality is null ? default : new Contract.Cardinality { Min = item.Cardinality.Min, Max = Contract.Optional<decimal?>.Some(item.Cardinality.Max) },
                        Table = item.Table is null ? default : ToTable(item.Table),
                    });
                    break;
                case State.FormItemKind.Content:
                    result.Add(new Contract.ContentFormViewItem { Key = item.Key, Content = (item.Content ?? []).Select(ToContent).ToArray() });
                    break;
                case State.FormItemKind.Action when item.Action is not null:
                    result.Add(new Contract.ActionFormViewItem { Key = item.Key, Action = ToAction(item.Action) });
                    break;
            }
        }
        return result;
    }

    private static Contract.ContentNode ToContent(State.ContentNode node) => node.Kind == State.ContentNodeKinds.Heading
        ? new Contract.HeadingContentNode { Text = ToText(node.Text), Level = node.Level is null ? default : node.Level.Value }
        : new Contract.ParagraphContentNode { Text = ToText(node.Text) };

    private static Contract.FormActionConfig ToAction(State.FormActionConfig action) => new()
    {
        Kind = action.Kind == State.FormActionKinds.OpenUrl ? Contract.FormActionKind.OpenUrl : Contract.FormActionKind.ScrollToSection,
        Label = ToText(action.Label),
        Url = action.Url is null ? default : action.Url,
        SectionId = action.SectionId is null ? default : action.SectionId,
    };

    private static Contract.CollectionTableConfig ToTable(State.CollectionTableConfig table) => new()
    {
        Columns = table.Columns is null
            ? default
            : table.Columns.ToDictionary(
                row => row.Key,
                row => new Contract.CollectionColumn { Width = ToWidth(row.Value.Width), Align = ToAlign(row.Value.Align) },
                StringComparer.Ordinal),
        Totals = table.Totals is null ? default : table.Totals.ToArray(),
    };

    private static Contract.Optional<Contract.FieldWidth> ToWidth(string? width) => width switch
    {
        "auto" => Contract.FieldWidth.Auto,
        "1/4" => Contract.FieldWidth.OneQuarter,
        "1/3" => Contract.FieldWidth.OneThird,
        "1/2" => Contract.FieldWidth.OneHalf,
        "2/3" => Contract.FieldWidth.TwoThirds,
        "3/4" => Contract.FieldWidth.ThreeQuarters,
        "full" => Contract.FieldWidth.Full,
        _ => default,
    };
}

