/// <summary>Carries the immutable audit payload associated with a committed mutation.</summary>
public sealed record FormMutationAuditEnvelope(
    string AuditId,
    EntityId InstanceId,
    TenantId Tenant,
    string ActorId,
    ReadOnlyMemory<byte> Payload,
    DateTimeOffset RecordedAt);

/// <summary>Carries the protected values and routing data awaiting projection delivery.</summary>
public sealed record FormProjectionEnvelope(
    string OutboxId,
    EntityId InstanceId,
    TenantId Tenant,
    Guid PartyId,
    string ActorId,
    FormDefinitionId FormId,
    SemanticVersion DefinitionVersion,
    string? CaseReference,
    ReadOnlyMemory<byte> ProtectedAcceptedValues,
    DateTimeOffset SubmittedAt,
    int Attempts = 0,
    string? LastErrorCode = null);

/// <summary>Groups the submission, audit, projection, and receipt committed as one unit.</summary>
public sealed record FormSubmissionCommit(
    string IdempotencyKey,
    FormSubmissionRecord Submission,
    FormMutationAuditEnvelope Audit,
    FormProjectionEnvelope Projection,
    FormSubmitReceipt Receipt);

/// <summary>Describes whether a submission commit was new, replayed, or conflicting.</summary>
public enum FormSubmissionCommitDisposition
{
    /// <summary>The submission created a new record.</summary>
    Created,
    /// <summary>The idempotency key replayed the prior result.</summary>
    Replayed,
    /// <summary>The idempotency key conflicts with a different request.</summary>
    Conflict
}

/// <summary>Returns the commit disposition and receipt when one exists.</summary>
public sealed record FormSubmissionCommitResult(
    FormSubmissionCommitDisposition Disposition,
    FormSubmitReceipt? Receipt);

/// <summary>One real submission-store exclusion scope. A commit publishes its complete envelope once.</summary>
public interface IFormSubmissionTransactionScope : IAsyncDisposable
{
    /// <summary>Atomically publishes the submission, audit, projection and receipt, reporting new, replayed or conflicting.</summary>
    ValueTask<FormSubmissionCommitResult> CommitAsync(FormSubmissionCommit commit, CancellationToken cancellationToken = default);
    /// <summary>Discards the scope's uncommitted work.</summary>
    ValueTask RollbackAsync(CancellationToken cancellationToken = default);
}

/// <summary>Persists submissions and manages leases for pending projections.</summary>
public interface IFormSubmissionTransactionStore
{
    /// <summary>Opens an exclusive transaction scope for one submission commit.</summary>
    ValueTask<IFormSubmissionTransactionScope> BeginTransactionAsync(CancellationToken cancellationToken = default);
    /// <summary>Atomically publishes the submission, audit, projection and receipt, reporting new, replayed or conflicting.</summary>
    ValueTask<FormSubmissionCommitResult> CommitAsync(FormSubmissionCommit commit, CancellationToken cancellationToken = default);
    /// <summary>Returns the tenant's stored submission for the instance, or null when absent.</summary>
    ValueTask<FormSubmissionRecord?> GetAsync(TenantId tenant, EntityId instanceId, CancellationToken cancellationToken = default);
    /// <summary>Leases up to the given number of undelivered projections so no other worker takes them.</summary>
    ValueTask<IReadOnlyList<FormProjectionEnvelope>> LeasePendingAsync(int maximum, CancellationToken cancellationToken = default);
    /// <summary>Returns a leased projection to the pending pool without recording an attempt.</summary>
    ValueTask ReleaseProjectionLeaseAsync(string outboxId, CancellationToken cancellationToken = default);
    /// <summary>Marks the projection delivered, recording its skips on the replayable receipt.</summary>
    ValueTask CompleteProjectionAsync(string outboxId, IReadOnlyList<FormProjectionSkip> skips, CancellationToken cancellationToken = default);
    /// <summary>Releases the lease and records a failed attempt with its stable error code.</summary>
    ValueTask RetryProjectionAsync(string outboxId, string stableErrorCode, CancellationToken cancellationToken = default);
}

namespace Harborline.Foundation.Forms.Engine.Persistence;

internal static class FormSubmissionStoreModel
{
    internal static void ValidateAtomicEnvelope(FormSubmissionCommit commit)
    {
        ArgumentNullException.ThrowIfNull(commit);
        if (string.IsNullOrWhiteSpace(commit.IdempotencyKey))
            throw new ArgumentException("Idempotency key is required.", nameof(commit));
        if (commit.Submission.InstanceId != commit.Audit.InstanceId || commit.Submission.InstanceId != commit.Projection.InstanceId)
            throw new ArgumentException("Submission, audit, and projection must name one instance.", nameof(commit));
        if (commit.Submission.Tenant != commit.Audit.Tenant || commit.Submission.Tenant != commit.Projection.Tenant)
            throw new ArgumentException("Submission, audit, and projection must name one tenant.", nameof(commit));
        if (commit.Submission.PartyId != commit.Projection.PartyId
            || !string.Equals(commit.Submission.ActorId, commit.Projection.ActorId, StringComparison.Ordinal))
            throw new ArgumentException("Submission and projection must name one Party and actor.", nameof(commit));
        if (commit.Submission.FormId != commit.Projection.FormId || commit.Submission.DefinitionVersion != commit.Projection.DefinitionVersion)
            throw new ArgumentException("Submission and projection must name one form definition version.", nameof(commit));
        if (commit.Submission.SubmittedAt != commit.Audit.RecordedAt
            || commit.Submission.SubmittedAt != commit.Projection.SubmittedAt
            || commit.Submission.SubmittedAt != commit.Receipt.SubmittedAt)
            throw new ArgumentException("Submission, audit, projection, and receipt must share one instant.", nameof(commit));
        if (commit.Submission.InstanceId != commit.Receipt.InstanceId)
            throw new ArgumentException("Receipt must name the committed instance.", nameof(commit));
        if (commit.Projection.Attempts != 0 || commit.Projection.LastErrorCode is not null)
            throw new ArgumentException("A new projection outbox row must begin without attempts or an error.", nameof(commit));
        if (commit.Receipt.ProjectionStatus != FormProjectionStatus.Pending || commit.Receipt.ProjectionSkips.Count != 0)
            throw new ArgumentException("A new submission receipt must begin pending without projection skips.", nameof(commit));
    }

    internal static FormSubmissionCommit Clone(FormSubmissionCommit value) => value with
    {
        Submission = Clone(value.Submission),
        Audit = Clone(value.Audit),
        Projection = Clone(value.Projection),
        Receipt = value.Receipt with { ProjectionSkips = value.Receipt.ProjectionSkips.ToArray() },
    };

    internal static FormSubmissionRecord Clone(FormSubmissionRecord value) =>
        value with { ProtectedAcceptedCandidate = value.ProtectedAcceptedCandidate.ToArray() };

    internal static FormMutationAuditEnvelope Clone(FormMutationAuditEnvelope value) =>
        value with { Payload = value.Payload.ToArray() };

    internal static FormProjectionEnvelope Clone(FormProjectionEnvelope value) =>
        value with { ProtectedAcceptedValues = value.ProtectedAcceptedValues.ToArray() };
}

using Harborline.Foundation.Assets.Common;

namespace Harborline.Foundation.Forms.Engine.Persistence;

/// <summary>Holds in-memory submission, audit, idempotency, lease, and projection state.</summary>
public sealed class InMemoryFormSubmissionState
{
    internal readonly SemaphoreSlim Gate = new(1, 1);
    internal readonly Dictionary<(TenantId Tenant, string Instance), FormSubmissionRecord> Submissions = new();
    internal readonly Dictionary<(TenantId Tenant, string Form, string Key), FormSubmissionCommit> Idempotency = new();
    internal readonly Dictionary<string, FormMutationAuditEnvelope> Audits = new(StringComparer.Ordinal);
    internal readonly Dictionary<string, FormProjectionEnvelope> Pending = new(StringComparer.Ordinal);
    internal readonly HashSet<string> Completed = new(StringComparer.Ordinal);
    internal readonly HashSet<string> Leased = new(StringComparer.Ordinal);
}

/// <summary>Provides a process-local transactional submission store for non-production hosts.</summary>
public sealed class InMemoryFormSubmissionStore : IFormSubmissionTransactionStore
{
    private readonly InMemoryFormSubmissionState _state;
    private readonly Func<FormSubmissionCommit, Exception?>? _commitFailure;

    /// <summary>Creates a process-local store with optional shared state for test isolation or inspection.</summary>
    public InMemoryFormSubmissionStore(InMemoryFormSubmissionState? state = null)
        : this(state ?? new InMemoryFormSubmissionState(), null) { }

    /// <summary>Creates the internal store variant with an injectable commit failure.</summary>
    internal InMemoryFormSubmissionStore(
        InMemoryFormSubmissionState state,
        Func<FormSubmissionCommit, Exception?>? commitFailure)
    {
        _state = state;
        _commitFailure = commitFailure;
    }

    /// <inheritdoc />
    public async ValueTask<FormSubmissionCommitResult> CommitAsync(
        FormSubmissionCommit commit,
        CancellationToken cancellationToken = default)
    {
        await using var transaction = await BeginTransactionAsync(cancellationToken).ConfigureAwait(false);
        return await transaction.CommitAsync(commit, cancellationToken).ConfigureAwait(false);
    }

    /// <inheritdoc />
    public async ValueTask<IFormSubmissionTransactionScope> BeginTransactionAsync(CancellationToken cancellationToken = default)
    {
        await _state.Gate.WaitAsync(cancellationToken).ConfigureAwait(false);
        return new Transaction(_state, _commitFailure);
    }

    private sealed class Transaction(
        InMemoryFormSubmissionState state,
        Func<FormSubmissionCommit, Exception?>? commitFailure) : IFormSubmissionTransactionScope
    {
        private bool _commitAttempted;
        private bool _released;

        /// <inheritdoc />
        public ValueTask<FormSubmissionCommitResult> CommitAsync(FormSubmissionCommit commit, CancellationToken cancellationToken = default)
        {
            ObjectDisposedException.ThrowIf(_released, this);
            if (_commitAttempted) throw new InvalidOperationException("A Forms submission scope can commit only once.");
            _commitAttempted = true;
            cancellationToken.ThrowIfCancellationRequested();
            ArgumentNullException.ThrowIfNull(commit);
            FormSubmissionStoreModel.ValidateAtomicEnvelope(commit);
            var key = (commit.Submission.Tenant, commit.Submission.FormId.Value, commit.IdempotencyKey);
            if (state.Idempotency.TryGetValue(key, out var existing))
                return ValueTask.FromResult(string.Equals(existing.Submission.RequestFingerprint, commit.Submission.RequestFingerprint, StringComparison.Ordinal)
                    ? new FormSubmissionCommitResult(FormSubmissionCommitDisposition.Replayed, existing.Receipt)
                    : new FormSubmissionCommitResult(FormSubmissionCommitDisposition.Conflict, null));

            if (state.Submissions.ContainsKey((commit.Submission.Tenant, commit.Submission.InstanceId.ToString()))
                || state.Audits.ContainsKey(commit.Audit.AuditId)
                || state.Pending.ContainsKey(commit.Projection.OutboxId)
                || state.Completed.Contains(commit.Projection.OutboxId))
                throw new ArgumentException("Submission, audit, and outbox identities must be unique.", nameof(commit));
            if (commitFailure?.Invoke(commit) is { } failure) throw failure;
            var snapshot = FormSubmissionStoreModel.Clone(commit);
            state.Submissions.Add((snapshot.Submission.Tenant, snapshot.Submission.InstanceId.ToString()), snapshot.Submission);
            state.Audits.Add(snapshot.Audit.AuditId, snapshot.Audit);
            state.Pending.Add(snapshot.Projection.OutboxId, snapshot.Projection);
            state.Idempotency.Add(key, snapshot);
            state.Leased.Add(snapshot.Projection.OutboxId);
            return ValueTask.FromResult(new FormSubmissionCommitResult(FormSubmissionCommitDisposition.Created, snapshot.Receipt));
        }

        /// <inheritdoc />
        public ValueTask RollbackAsync(CancellationToken cancellationToken = default)
        {
            Release();
            return ValueTask.CompletedTask;
        }

        /// <inheritdoc />
        public ValueTask DisposeAsync()
        {
            Release();
            return ValueTask.CompletedTask;
        }

        private void Release()
        {
            if (_released) return;
            _released = true;
            state.Gate.Release();
        }
    }

    /// <inheritdoc />
    public async ValueTask<FormSubmissionRecord?> GetAsync(
        TenantId tenant,
        EntityId instanceId,
        CancellationToken cancellationToken = default)
    {
        await _state.Gate.WaitAsync(cancellationToken).ConfigureAwait(false);
        try { return _state.Submissions.TryGetValue((tenant, instanceId.ToString()), out var value) ? FormSubmissionStoreModel.Clone(value) : null; }
        finally { _state.Gate.Release(); }
    }

    /// <inheritdoc />
    public async ValueTask<IReadOnlyList<FormProjectionEnvelope>> LeasePendingAsync(
        int maximum,
        CancellationToken cancellationToken = default)
    {
        if (maximum is <= 0 or > 1000) throw new ArgumentOutOfRangeException(nameof(maximum));
        await _state.Gate.WaitAsync(cancellationToken).ConfigureAwait(false);
        try
        {
            var rows = _state.Pending.Values.Where(row => !_state.Leased.Contains(row.OutboxId))
                .OrderBy(row => row.SubmittedAt).ThenBy(row => row.OutboxId, StringComparer.Ordinal).Take(maximum).ToArray();
            foreach (var row in rows) _state.Leased.Add(row.OutboxId);
            return rows.Select(FormSubmissionStoreModel.Clone).ToArray();
        }
        finally { _state.Gate.Release(); }
    }

    /// <inheritdoc />
    public async ValueTask ReleaseProjectionLeaseAsync(string outboxId, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(outboxId);
        await _state.Gate.WaitAsync(cancellationToken).ConfigureAwait(false);
        try { _state.Leased.Remove(outboxId); }
        finally { _state.Gate.Release(); }
    }

    /// <inheritdoc />
    public async ValueTask CompleteProjectionAsync(string outboxId, IReadOnlyList<FormProjectionSkip> skips, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(skips);
        await _state.Gate.WaitAsync(cancellationToken).ConfigureAwait(false);
        try
        {
            _state.Leased.Remove(outboxId);
            if (!_state.Pending.Remove(outboxId)) return;
            _state.Completed.Add(outboxId);
            foreach (var (key, commit) in _state.Idempotency.ToArray())
            {
                if (commit.Projection.OutboxId != outboxId) continue;
                var receipt = commit.Receipt with { ProjectionStatus = FormProjectionStatus.Complete, ProjectionSkips = skips.ToArray() };
                _state.Idempotency[key] = commit with { Receipt = receipt };
                break;
            }
        }
        finally { _state.Gate.Release(); }
    }

    /// <inheritdoc />
    public async ValueTask RetryProjectionAsync(string outboxId, string stableErrorCode, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(stableErrorCode);
        await _state.Gate.WaitAsync(cancellationToken).ConfigureAwait(false);
        try
        {
            _state.Leased.Remove(outboxId);
            if (_state.Pending.TryGetValue(outboxId, out var value))
                _state.Pending[outboxId] = value with { Attempts = checked(value.Attempts + 1), LastErrorCode = stableErrorCode };
        }
        finally { _state.Gate.Release(); }
    }

    internal async ValueTask<(int Submissions, int Audits, int Pending, int Completed)> CountsAsync()
    {
        await _state.Gate.WaitAsync().ConfigureAwait(false);
        try { return (_state.Submissions.Count, _state.Audits.Count, _state.Pending.Count, _state.Completed.Count); }
        finally { _state.Gate.Release(); }
    }

}

