/// <summary>Reports projection fields that were skipped during delivery.</summary>
public sealed record FormProjectionDeliveryResult(IReadOnlyList<FormProjectionSkip> Skips);

/// <summary>Delivers a committed form projection to the host's projection sink.</summary>
public interface IFormProjectionSink
{
    /// <summary>Delivers the projection to the host and returns the fields it skipped.</summary>
    ValueTask<FormProjectionDeliveryResult> DeliverAsync(
        FormProjectionEnvelope envelope,
        CancellationToken cancellationToken = default);
}

using Harborline.Foundation.Forms.Engine.Persistence;

namespace Harborline.Foundation.Forms.Engine.Projection;

internal static class FormProjectionRecovery
{
    internal static async ValueTask<FormProjectionRecoveryResult> RecoverAsync(
        IFormSubmissionTransactionStore submissions,
        IFormProjectionSink projections,
        int maximumDeliveries,
        CancellationToken cancellationToken)
    {
        var rows = await submissions.LeasePendingAsync(maximumDeliveries, cancellationToken).ConfigureAwait(false);
        var completed = 0;
        for (var index = 0; index < rows.Count; index++)
        {
            var row = rows[index];
            try
            {
                var result = await projections.DeliverAsync(row, cancellationToken).ConfigureAwait(false);
                await submissions.CompleteProjectionAsync(row.OutboxId, result.Skips, cancellationToken).ConfigureAwait(false);
                completed++;
            }
            catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
            {
                for (var releaseIndex = index; releaseIndex < rows.Count; releaseIndex++)
                {
                    try { await submissions.ReleaseProjectionLeaseAsync(rows[releaseIndex].OutboxId, CancellationToken.None).ConfigureAwait(false); }
                    catch { }
                }
                throw;
            }
            catch { await submissions.RetryProjectionAsync(row.OutboxId, "form.engine.projection-pending", CancellationToken.None).ConfigureAwait(false); }
        }
        return new(rows.Count, completed, rows.Count - completed);
    }
}

using Contract = Harborline.Contracts.Forms;
using Harborline.Foundation.Forms;
using Harborline.Foundation.Forms.Exceptions;
using Harborline.Foundation.Forms.Models;
using Harborline.Foundation.RuleEngine.Compilation;

namespace Harborline.Foundation.Forms.Engine;

/// <summary>
/// Rejects definitions whose Tier-2 rules or page guards cannot compile on the
/// same .NET rule runtime used by render and submit.
/// </summary>
public static class RuleCompileAdmission
{
    /// <summary>
    /// Compiles the complete Tier-2 rule set and every page visibility guard.
    /// Authoring hosts must invoke this before persisting a definition revision.
    /// </summary>
    public static void ValidateOrThrow(FormDefinition definition)
    {
        ArgumentNullException.ThrowIfNull(definition);

        if (definition.Overlay.Rules.Count > 0)
        {
            try
            {
                _ = RuleCompiler.Compile(definition.Overlay.Rules.Select(FormContractMapper.ToContractRule).ToArray());
            }
            catch (RuleCompilationException exception)
            {
                var subject = string.IsNullOrWhiteSpace(exception.RuleId)
                    ? "the rule set"
                    : $"rule '{exception.RuleId}'";
                throw new FormDefinitionValidationException(
                    definition.Id,
                    $"{subject} does not compile ({exception.Code}): {exception.Message}",
                    FormDefinitionCodes.RulesUncompilable);
            }
        }

        foreach (var page in definition.Overlay.Pages ?? Array.Empty<FormPage>())
        {
            if (string.IsNullOrWhiteSpace(page.VisibleWhen))
            {
                continue;
            }

            var guard = new Contract.RuleDefinition
            {
                Id = $"page-guard:{page.Id}",
                Tier = Contract.RuleTier.JsonLogic,
                Scope = Contract.RuleScope.Schema,
                ScopeTarget = string.Empty,
                Expression = page.VisibleWhen,
                Action = Contract.RuleActionKind.Validate,
            };

            try
            {
                _ = RuleCompiler.Compile([guard]);
            }
            catch (RuleCompilationException exception)
            {
                throw new FormDefinitionValidationException(
                    definition.Id,
                    $"page '{page.Id}' has a VisibleWhen guard that does not compile ({exception.Code}): {exception.Message}",
                    FormDefinitionCodes.RulesGuardUncompilable,
                    page.Id);
            }
        }
    }
}

