using Harborline.Foundation.Forms.Engine.Projection;
using Xunit;

namespace Harborline.Foundation.Forms.Engine.Tests;

public sealed class FileJournalFormSubmissionStoreTests
{
    private static readonly TenantId Tenant = new("tenant-engine");
    private static readonly EntityId Instance = new("harborline", "forms", "restart-probe");

    [Fact]
    public async Task SaveAsync_DurableAdapterSurvivesProcessRestart()
    {
        using var fixture = new JournalFixture();
        await RunWriterProcessAsync(fixture.JournalPath, "write-crash");

        using var restarted = fixture.Open();
        var submission = await restarted.GetAsync(Tenant, Instance);
        var pending = Assert.Single(await restarted.LeasePendingAsync(10));

        Assert.NotNull(submission);
        Assert.Equal("restart-fingerprint", submission.RequestFingerprint);
        Assert.Equal("outbox-restart", pending.OutboxId);
        Assert.Equal((1, 1, 1, 0), await restarted.CountsAsync());
    }

    [Fact]
    public async Task ProjectionDelivery_RestartRecoversPendingRows()
    {
        using var fixture = new JournalFixture();
        await RunWriterProcessAsync(fixture.JournalPath, "write-crash");
        var projection = new RecordingProjection();
        using (var restarted = fixture.Open())
        {
            var result = await FormProjectionRecovery.RecoverAsync(restarted, projection, 10, default);
            Assert.Equal(new FormProjectionRecoveryResult(1, 1, 0), result);
            Assert.Equal("outbox-restart", Assert.Single(projection.Delivered).OutboxId);
            Assert.Empty(await restarted.LeasePendingAsync(10));
            Assert.Equal((1, 1, 0, 1), await restarted.CountsAsync());
        }
        using var afterAcknowledgementRestart = fixture.Open();
        Assert.Empty(await afterAcknowledgementRestart.LeasePendingAsync(10));
        Assert.Equal((1, 1, 0, 1), await afterAcknowledgementRestart.CountsAsync());
    }

    [Fact]
    public async Task IncompleteFinalFrame_IsTruncatedWithoutLosingCommittedRows()
    {
        using var fixture = new JournalFixture();
        await RunWriterProcessAsync(fixture.JournalPath, "write-partial-crash");
        var committedLength = new FileInfo(fixture.JournalPath).Length;

        using var restarted = fixture.Open();

        Assert.NotNull(await restarted.GetAsync(Tenant, Instance));
        Assert.Equal(committedLength - 3, new FileInfo(fixture.JournalPath).Length);
    }

    [Fact]
    public async Task CorruptCompleteFrame_FailsClosed()
    {
        using var fixture = new JournalFixture();
        await RunWriterProcessAsync(fixture.JournalPath, "write-crash");
        using (var stream = new FileStream(fixture.JournalPath, FileMode.Open, FileAccess.ReadWrite, FileShare.None))
        {
            stream.Position = 20;
            var value = stream.ReadByte();
            stream.Position = 20;
            stream.WriteByte((byte)(value ^ 0xff));
            stream.Flush(flushToDisk: true);
        }

        Assert.Throws<InvalidDataException>(() => fixture.Open());
    }

    [Fact]
    public async Task CorruptLengthField_FailsClosedWithoutTruncatingCommittedFrame()
    {
        using var fixture = new JournalFixture();
        await RunWriterProcessAsync(fixture.JournalPath, "write-crash");
        var committedLength = new FileInfo(fixture.JournalPath).Length;
        using (var stream = new FileStream(fixture.JournalPath, FileMode.Open, FileAccess.ReadWrite, FileShare.None))
        {
            var length = new byte[4];
            stream.Position = 8;
            stream.ReadExactly(length);
            BinaryPrimitives.WriteInt32LittleEndian(length, checked(BinaryPrimitives.ReadInt32LittleEndian(length) + 1024));
            stream.Position = 8;
            stream.Write(length);
            stream.Flush(flushToDisk: true);
        }

        Assert.Throws<InvalidDataException>(() => fixture.Open());
        Assert.Equal(committedLength, new FileInfo(fixture.JournalPath).Length);
    }

    [Fact]
    public async Task ConcurrentRecovery_LeasesEachPendingEnvelopeOnce()
    {
        using var fixture = new JournalFixture();
        await RunWriterProcessAsync(fixture.JournalPath, "write-crash");
        using var store = fixture.Open();
        var blocking = new BlockingProjection();
        var first = FormProjectionRecovery.RecoverAsync(store, blocking, 10, default).AsTask();
        await blocking.Started.Task.WaitAsync(TimeSpan.FromSeconds(10));

        var secondProjection = new RecordingProjection();
        var second = await FormProjectionRecovery.RecoverAsync(store, secondProjection, 10, default);
        blocking.Release.TrySetResult();
        var firstResult = await first;

        Assert.Equal(new FormProjectionRecoveryResult(0, 0, 0), second);
        Assert.Empty(secondProjection.Delivered);
        Assert.Equal(new FormProjectionRecoveryResult(1, 1, 0), firstResult);
    }

    [Fact]
    public async Task AdapterLifetime_HoldsExclusiveProcessLock()
    {
        using var fixture = new JournalFixture();
        using var first = fixture.Open();
        Assert.Throws<IOException>(() => fixture.Open());
        await Task.CompletedTask;
    }

    [Fact]
    public async Task SubmissionScope_RollbackWritesNoJournalFrameAndReopeningStartsEmpty()
    {
        using var fixture = new JournalFixture();
        using (var store = fixture.Open())
        {
            await using var scope = await store.BeginTransactionAsync();
            await scope.RollbackAsync();
            Assert.Equal((0, 0, 0, 0), await store.CountsAsync());
        }

        using var reopened = fixture.Open();
        Assert.Equal((0, 0, 0, 0), await reopened.CountsAsync());
        Assert.Equal(0, new FileInfo(fixture.JournalPath).Length);
    }

    [Fact]
    public void FileSubmissionStore_RegistersSingletonAndRefusesLayering()
    {
        using var fixture = new JournalFixture();
        var services = new Microsoft.Extensions.DependencyInjection.ServiceCollection();
        services.AddHarborlineFormsEngineFileSubmissionStore(options => options.JournalPath = fixture.JournalPath);

        Assert.Equal(
            Microsoft.Extensions.DependencyInjection.ServiceLifetime.Singleton,
            Assert.Single(services, row => row.ServiceType == typeof(IFormSubmissionTransactionStore)).Lifetime);
        Assert.Throws<InvalidOperationException>(() =>
            services.AddHarborlineFormsEngineFileSubmissionStore(options => options.JournalPath = fixture.JournalPath));
    }

    private static async Task RunWriterProcessAsync(string journalPath, string mode)
    {
        var root = FindRepositoryRoot();
        var configuration = new DirectoryInfo(AppContext.BaseDirectory).Parent!.Name;
        var probe = Path.Combine(
            root,
            "projections/dotnet/foundation/hlp.foundation.forms-engine.restart-probe/bin",
            configuration,
            "net11.0",
            "Harborline.Foundation.Forms.Engine.RestartProbe.dll");
        Assert.True(File.Exists(probe), $"Restart probe was not built: {probe}");
        var start = new ProcessStartInfo(ResolveDotnetMuxer())
        {
            WorkingDirectory = root,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
        };
        start.ArgumentList.Add(probe);
        start.ArgumentList.Add(mode);
        start.ArgumentList.Add(journalPath);
        using var process = Process.Start(start) ?? throw new InvalidOperationException("Could not start restart probe.");
        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(30));
        await process.WaitForExitAsync(timeout.Token);
        var stdout = await process.StandardOutput.ReadToEndAsync(timeout.Token);
        var stderr = await process.StandardError.ReadToEndAsync(timeout.Token);
        Assert.True(process.ExitCode == 0, $"Restart probe failed ({process.ExitCode}): {stderr}");
        Assert.Contains("written", stdout, StringComparison.Ordinal);
    }

    private static string ResolveDotnetMuxer()
    {
        // Environment.ProcessPath is the dotnet muxer only where the test host runs under
        // `dotnet exec testhost.dll` (macOS/Linux). On Windows VSTest launches testhost.exe,
        // an apphost, and re-invoking that with a DLL argument fails host resolution
        // ("hostpolicy.dll was not found"). Resolve the muxer the same way the tooling's
        // resolve-dotnet.mjs does: DOTNET_HOST_PATH first, then the muxer that owns the
        // running runtime, then ProcessPath only when it actually is the muxer.
        var muxerFileName = OperatingSystem.IsWindows() ? "dotnet.exe" : "dotnet";
        var hostPath = Environment.GetEnvironmentVariable("DOTNET_HOST_PATH");
        if (!string.IsNullOrEmpty(hostPath) && File.Exists(hostPath)) return hostPath;
        var runtimeDirectory = System.Runtime.InteropServices.RuntimeEnvironment.GetRuntimeDirectory();
        var fromRuntime = Path.GetFullPath(Path.Combine(runtimeDirectory, "..", "..", "..", muxerFileName));
        if (File.Exists(fromRuntime)) return fromRuntime;
        var processPath = Environment.ProcessPath;
        if (processPath is not null
            && Path.GetFileName(processPath).Equals(muxerFileName, StringComparison.OrdinalIgnoreCase)) return processPath;
        throw new InvalidOperationException("Could not resolve the dotnet muxer for the restart probe.");
    }

    private static string FindRepositoryRoot()
    {
        for (var directory = new DirectoryInfo(AppContext.BaseDirectory); directory is not null; directory = directory.Parent)
        {
            if (File.Exists(Path.Combine(directory.FullName, "Harborline.Platform.slnx"))) return directory.FullName;
        }
        throw new InvalidOperationException("Could not locate the Harborline Platform repository root.");
    }

    private sealed class RecordingProjection : IFormProjectionSink
    {
        public List<FormProjectionEnvelope> Delivered { get; } = [];

        public ValueTask<FormProjectionDeliveryResult> DeliverAsync(
            FormProjectionEnvelope envelope,
            CancellationToken cancellationToken = default)
        {
            Delivered.Add(envelope);
            return ValueTask.FromResult(new FormProjectionDeliveryResult([]));
        }
    }

    private sealed class BlockingProjection : IFormProjectionSink
    {
        public TaskCompletionSource Started { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public TaskCompletionSource Release { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);

        public async ValueTask<FormProjectionDeliveryResult> DeliverAsync(
            FormProjectionEnvelope envelope,
            CancellationToken cancellationToken = default)
        {
            Started.TrySetResult();
            await Release.Task.WaitAsync(cancellationToken);
            return new([]);
        }
    }

    private sealed class JournalFixture : IDisposable
    {
        private readonly string _directory = Path.Combine(Path.GetTempPath(), $"harborline-forms-journal-{Guid.NewGuid():N}");

        public JournalFixture()
        {
            Directory.CreateDirectory(_directory);
            JournalPath = Path.Combine(_directory, "submissions.hlfj");
        }

        public string JournalPath { get; }

        public FileJournalFormSubmissionStore Open() => new(new() { JournalPath = JournalPath });

        public void Dispose()
        {
            if (Directory.Exists(_directory)) Directory.Delete(_directory, recursive: true);
        }
    }
}

using System.Text.Json;
using Harborline.Contracts.Authorization;
using Harborline.Foundation.Assets.Common;
using Harborline.Foundation.Forms.Models;
using Xunit;
using Harness = Harborline.Foundation.Forms.Engine.Tests.FormEngineOrchestrationTests.Harness;

namespace Harborline.Foundation.Forms.Engine.Tests;

/// <summary>
/// DES-0016 forms-eng-8 (T-485 slice 4, L342, L358): permission to submit a form implies reading its
/// blank form with no separate read permission. It implies nothing about reading a submission.
/// </summary>
public sealed class FormBlankReadEngineTests
{
    private static readonly SubmitGate InspectorGate = new(Role: RoleReference.Domain("inspector"));
    private static readonly HashSet<FormEngineAction> SubmitOnly = [FormEngineAction.Submit];

    [Fact(DisplayName = "forms-eng-8: a principal permitted only to submit reads the blank form without a separate read permission")]
    public async Task SubmitPermissionReadsBlankForm()
    {
        var harness = await Harness.CreateAsync(grantedActions: SubmitOnly);

        var view = await harness.Engine.RenderAsync(harness.Definition.Id, null);

        Assert.NotNull(view);
        Assert.Equal([FormEngineAction.Read, FormEngineAction.Submit], harness.Context.Actions);
    }

    [Fact(DisplayName = "forms-eng-8: permission to submit does not imply reading an existing submission")]
    public async Task SubmitPermissionDoesNotReadSubmission()
    {
        var harness = await Harness.CreateAsync(grantedActions: SubmitOnly);
        using var candidate = JsonDocument.Parse("""{"name":"Ada"}""");
        var receipt = await harness.Engine.SubmitAsync(new(harness.Definition.Id, candidate, "idem"));

        await Assert.ThrowsAsync<FormEngineDeniedException>(
            async () => await harness.Engine.RenderAsync(harness.Definition.Id, receipt.InstanceId));
    }

    [Fact(DisplayName = "forms-eng-8: submit permission implies the blank read only for a principal the form's own gate admits")]
    public async Task ImpliedBlankReadPassesTheFormsGate()
    {
        var refused = new GateAccess(satisfied: false);
        var denied = await Harness.CreateAsync(definitionFactory: Gated, submitGates: refused, grantedActions: SubmitOnly);
        await Assert.ThrowsAsync<FormEngineDeniedException>(
            async () => await denied.Engine.RenderAsync(denied.Definition.Id, null));
        Assert.Equal([InspectorGate], refused.Asked);

        var admitted = new GateAccess(satisfied: true);
        var allowed = await Harness.CreateAsync(definitionFactory: Gated, submitGates: admitted, grantedActions: SubmitOnly);
        Assert.NotNull(await allowed.Engine.RenderAsync(allowed.Definition.Id, null));
        Assert.Equal([InspectorGate], admitted.Asked);
    }

    [Fact(DisplayName = "forms-eng-8: a principal with the read permission reads the blank form without the submit gate being asked")]
    public async Task ReadPermissionDoesNotAskTheSubmitGate()
    {
        var gates = new GateAccess(satisfied: false);
        var harness = await Harness.CreateAsync(definitionFactory: Gated, submitGates: gates, grantedActions: new HashSet<FormEngineAction> { FormEngineAction.Read });

        Assert.NotNull(await harness.Engine.RenderAsync(harness.Definition.Id, null));
        Assert.Empty(gates.Asked);
        Assert.Equal([FormEngineAction.Read], harness.Context.Actions);
    }

    private static FormDefinition Gated(string schemaId, TenantId tenant) =>
        Harness.CreateDefinition(schemaId, tenant) with { SubmitGate = InspectorGate };

    private sealed class GateAccess(bool satisfied) : IFormSubmitGateAccess
    {
        public List<SubmitGate> Asked { get; } = [];
        public ValueTask<bool> SatisfiesAsync(FormExecutionScope scope, FormDefinition definition, SubmitGate gate, CancellationToken cancellationToken = default)
        {
            Asked.Add(gate);
            return ValueTask.FromResult(satisfied);
        }
    }
}

using System.Text;
using Harborline.Foundation.Assets.Common;
using Harborline.Foundation.Forms.Engine.Capabilities;
using Xunit;

namespace Harborline.Foundation.Forms.Engine.Tests;

public sealed class FormCapabilityVerificationTests
{
    private static readonly byte[] Key = Encoding.UTF8.GetBytes("forms-root-key-for-tests-only");
    private static readonly DateTimeOffset Now = DateTimeOffset.Parse("2026-08-08T12:00:00Z");

    [Fact]
    public async Task VerifyAsync_MalformedEncodingSignatureOrUnknownKey_DeniesWithoutSecretEcho()
    {
        var validCaveats = Caveats("action = read");
        var malformed = "bearer-secret%%%";
        var badSignature = FormMacaroonCodec.EncodeSigned(MacaroonFormCapabilityIssuer.DefaultLocation, Identifier(FormCapabilityAction.Read), validCaveats, "wrong-secret-key"u8);
        var unknownKey = FormMacaroonCodec.EncodeSigned("unknown-location-secret", Identifier(FormCapabilityAction.Read), validCaveats, Key);
        var verifier = new MacaroonFormCapabilityVerifier(new TestKeys(Key));

        var errors = new[]
        {
            await DeniedAsync(verifier, malformed),
            await DeniedAsync(verifier, badSignature),
            await DeniedAsync(verifier, unknownKey),
        };

        Assert.All(errors, error =>
        {
            Assert.Equal("form.engine.denied", error.Code);
            Assert.Equal("The form capability was denied.", error.Message);
            Assert.DoesNotContain("secret", error.Message, StringComparison.OrdinalIgnoreCase);
            Assert.DoesNotContain("tenant-a", error.Message, StringComparison.Ordinal);
            Assert.DoesNotContain("secret", error.ToString(), StringComparison.OrdinalIgnoreCase);
        });
    }

    [Fact]
    public async Task VerifyAsync_MalformedUnknownMissingDuplicateOrEmptyCaveat_Denies()
    {
        var cases = new IReadOnlyList<string>[]
        {
            ["tenant tenant-a", "subject = alice", $"expires = {Now.AddMinutes(5):O}", "action = read"],
            ["tenant = tenant-a", "subject = alice", $"expires = {Now.AddMinutes(5):O}", "unknown = value", "action = read"],
            ["subject = alice", $"expires = {Now.AddMinutes(5):O}", "action = read"],
            ["tenant = tenant-a", "tenant = tenant-b", "subject = alice", $"expires = {Now.AddMinutes(5):O}", "action = read"],
            ["tenant = ", "subject = alice", $"expires = {Now.AddMinutes(5):O}", "action = read"],
            ["tenant = tenant-a", "subject = ", $"expires = {Now.AddMinutes(5):O}", "action = read"],
            ["tenant = tenant-a", "subject = alice", $"expires = {Now.AddMinutes(5):O}", "action = "],
            ["tenant = tenant-a", "subject = alice", $"expires = {Now.AddMinutes(5):O}", "role = "],
            ["tenant = tenant-a", "subject = alice", $"expires = {Now.AddMinutes(5):O}", "action = read", "action = write"],
        };
        var verifier = new MacaroonFormCapabilityVerifier(new TestKeys(Key));

        foreach (var caveats in cases)
        {
            var bearer = FormMacaroonCodec.EncodeSigned(MacaroonFormCapabilityIssuer.DefaultLocation, Identifier(FormCapabilityAction.Read), caveats, Key);
            var error = await DeniedAsync(verifier, bearer);
            Assert.Equal("form.engine.denied", error.Code);
        }
    }

    [Fact]
    public async Task VerifyAsync_UnknownActionInvalidExpiryOrExpiredCapability_Denies()
    {
        var cases = new[]
        {
            Caveats("action = delete"),
            new[] { "tenant = tenant-a", "subject = alice", "expires = yesterday", "action = read" },
            new[] { "tenant = tenant-a", "subject = alice", $"expires = {Now.AddTicks(-1):O}", "action = read" },
        };
        var verifier = new MacaroonFormCapabilityVerifier(new TestKeys(Key));

        foreach (var caveats in cases)
        {
            var bearer = FormMacaroonCodec.EncodeSigned(MacaroonFormCapabilityIssuer.DefaultLocation, Identifier(FormCapabilityAction.Read), caveats, Key);
            await DeniedAsync(verifier, bearer);
        }
    }

    [Fact]
    public async Task IssuerAndVerifier_PreserveClaimsAndExpiryBoundaryButDiscardBearerRoles()
    {
        var keys = new TestKeys(Key);
        var issuer = new MacaroonFormCapabilityIssuer(keys);
        var verifier = new MacaroonFormCapabilityVerifier(keys);
        var bearer = await issuer.IssueAsync(
            new TenantId("tenant-a"),
            "alice",
            ["bearer-admin", "bearer-admin"],
            [FormCapabilityAction.Read],
            Now.AddMinutes(5));

        var capability = await verifier.VerifyAsync(bearer, Now.AddMinutes(5));

        Assert.Equal(new TenantId("tenant-a"), capability.Tenant);
        Assert.Equal("alice", capability.Subject);
        Assert.Equal([FormCapabilityAction.Read], capability.Actions.ToArray());
        Assert.DoesNotContain(capability.GetType().GetProperties(), property => property.Name.Contains("Role", StringComparison.Ordinal));
    }

    [Fact]
    public async Task PinnedSourceWireVector_PreservesWireAndHmacButLegacyIdentifierDenies()
    {
        var key = Enumerable.Range(0, 32).Select(value => (byte)value).ToArray();
        const string bearer = "c3VuZmlzaC9mb3Jtcx4wMDExMjIzMzQ0NTU2Njc3ODg5OWFhYmJjY2RkZWVmZh50ZW5hbnQgPSB0ZW5hbnQ6YWNtZR5zdWJqZWN0ID0gdXNlcjphbGljZR5leHBpcmVzID0gMjAzMC0wMS0wMlQwMzowNDowNS4wMDAwMDAwKzAwOjAwHnJvbGUgPSByZWFkZXIeYWN0aW9uID0gcmVhZB_kobxyxkcErdCJV-f2-USYB-NtAN_itJuEPvH5Fhv2bg";
        var decoded = FormMacaroonCodec.Decode(bearer);
        var expected = FormMacaroonCodec.ComputeChain(key, decoded.Identifier, decoded.Caveats);
        var verifier = new MacaroonFormCapabilityVerifier(new TestKeys(key));

        Assert.Equal("sunfish/forms", decoded.Location);
        // The issuer default is pinned to the same wire location this captured vector carries;
        // every other test in this file spells it as the constant, so this line is what keeps the
        // constant honest against the wire.
        Assert.Equal(MacaroonFormCapabilityIssuer.DefaultLocation, decoded.Location);
        Assert.Equal("00112233445566778899aabbccddeeff", decoded.Identifier);
        Assert.True(System.Security.Cryptography.CryptographicOperations.FixedTimeEquals(expected, decoded.Signature));
        await DeniedAsync(verifier, bearer);
    }

    [Fact]
    public async Task VerifyAsync_ActionlessLegacyTokenAttenuatedWithWrite_Denies()
    {
        var original = FormMacaroonCodec.Decode(
            FormMacaroonCodec.EncodeSigned(MacaroonFormCapabilityIssuer.DefaultLocation, "legacy-source", Caveats(), Key));
        var appended = "action = write";
        var caveats = original.Caveats.Append(appended).ToArray();
        var signature = System.Security.Cryptography.HMACSHA256.HashData(original.Signature, Encoding.UTF8.GetBytes(appended));
        var bearer = FormMacaroonCodec.EncodeWithSignature(original.Location, original.Identifier, caveats, signature);
        var verifier = new MacaroonFormCapabilityVerifier(new TestKeys(Key));

        await DeniedAsync(verifier, bearer);
    }

    [Fact]
    public async Task IssueAsync_OversizedOrSeparatorBearingCapability_RejectsBeforeKeyLookup()
    {
        var keys = new CountingKeys(Key);
        var issuer = new MacaroonFormCapabilityIssuer(keys);

        await Assert.ThrowsAsync<ArgumentException>(async () => await issuer.IssueAsync(
            new TenantId("tenant-a"), "alice", Enumerable.Repeat("role", 61).ToArray(),
            [FormCapabilityAction.Read], Now.AddMinutes(5)));
        await Assert.ThrowsAsync<ArgumentException>(async () => await issuer.IssueAsync(
            new TenantId("tenant-a"), new string('a', 2049), [],
            [FormCapabilityAction.Read], Now.AddMinutes(5)));
        await Assert.ThrowsAsync<ArgumentException>(async () => await issuer.IssueAsync(
            new TenantId("tenant-a"), "alice", ["role\u001eadmin"],
            [FormCapabilityAction.Read], Now.AddMinutes(5)));

        Assert.Equal(0, keys.CallCount);
    }

    internal static IReadOnlyList<string> Caveats(params string[] additional) =>
        ["tenant = tenant-a", "subject = alice", $"expires = {Now.AddMinutes(5):O}", .. additional];

    private static string Identifier(FormCapabilityAction action) =>
        $"hlf1:{(action == FormCapabilityAction.Read ? "read" : "write")}:{Guid.NewGuid():N}";

    private static async Task<FormCapabilityDeniedException> DeniedAsync(
        IFormCapabilityVerifier verifier,
        string bearer) =>
        await Assert.ThrowsAsync<FormCapabilityDeniedException>(async () =>
            await verifier.VerifyAsync(bearer, Now));

    internal sealed class TestKeys(byte[] key) : IFormCapabilityRootKeyProvider
    {
        public ValueTask<ReadOnlyMemory<byte>?> GetRootKeyAsync(
            string location,
            CancellationToken cancellationToken = default) =>
            ValueTask.FromResult<ReadOnlyMemory<byte>?>(
                string.Equals(location, MacaroonFormCapabilityIssuer.DefaultLocation, StringComparison.Ordinal)
                    ? key.AsMemory()
                    : null);
    }

    private sealed class CountingKeys(byte[] key) : IFormCapabilityRootKeyProvider
    {
        public int CallCount { get; private set; }

        public ValueTask<ReadOnlyMemory<byte>?> GetRootKeyAsync(
            string location,
            CancellationToken cancellationToken = default)
        {
            CallCount++;
            return ValueTask.FromResult<ReadOnlyMemory<byte>?>(key.AsMemory());
        }
    }
}

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Harborline.Foundation.Forms.Engine.DependencyInjection;
using Xunit;

namespace Harborline.Foundation.Forms.Engine.Tests;

public sealed class FormEngineCompositionTests
{
    [Fact]
    public void ProductionComposition_MissingProtectionGovernanceOrAuditProvider_FailsStartup()
    {
        var services = new ServiceCollection();
        var error = Assert.Throws<InvalidOperationException>(() =>
            services.AddHarborlineFormsEngine(FormEngineHostEnvironment.Production));
        Assert.Contains(nameof(IFormExecutionContextProvider), error.Message, StringComparison.Ordinal);
        Assert.Contains("IFormFieldSecurity", error.Message, StringComparison.Ordinal);
        Assert.Contains("IFormProjectionSink", error.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void In_memory_submission_adapter_refuses_production()
    {
        var services = new ServiceCollection();
        Assert.Throws<InvalidOperationException>(() =>
            services.AddHarborlineFormsEngineInMemorySubmissionStore(FormEngineHostEnvironment.Production));
    }

    [Fact]
    public void ProductionCompositionRequiresExactlyTheHostSuppliedClock()
    {
        var missing = GovernanceEnforcementTests.ProductionPortShell();
        missing.RemoveAll<TimeProvider>();
        var error = Assert.Throws<InvalidOperationException>(() =>
            missing.AddHarborlineFormsEngine(FormEngineHostEnvironment.Production));
        Assert.Contains(nameof(TimeProvider), error.Message, StringComparison.Ordinal);

        var supplied = GovernanceEnforcementTests.ProductionPortShell();
        var hostClock = Assert.Single(supplied, row => row.ServiceType == typeof(TimeProvider)).ImplementationInstance;
        supplied.AddSingleton<Security.IFormTenantProtectionKeyProvider, FormFieldSecurityHarness.FixedTenantKeyProvider>();
        supplied.AddSingleton<Security.IFormDecryptCapabilityProvider>(
            new FormFieldSecurityHarness.StubDecryptCapabilityProvider(true));
        supplied.AddHarborlineFormsEngineTenantBoundFieldSecurity(
            new Security.FormFieldSecurityOptions { HostJurisdiction = "US" });
        supplied.AddHarborlineFormsEngine(FormEngineHostEnvironment.Production);

        Assert.Single(supplied, row => row.ServiceType == typeof(TimeProvider));
        using var provider = supplied.BuildServiceProvider();
        Assert.Same(hostClock, provider.GetRequiredService<TimeProvider>());
    }

    [Fact]
    public void ProductionCompositionRefusesMultipleHostClocks()
