namespace Harborline.Foundation.Forms.Engine.Tests;

internal sealed class FormFieldSecurityHarness
{
    private FormFieldSecurityHarness(
        FormEngineOrchestrationTests.Harness engineHarness,
        RecordingFormSecurityAudit audit,
        FixedTenantKeyProvider keys,
        StubDecryptCapabilityProvider capabilities,
        IFormFieldSecurity security)
        => (EngineHarness, Audit, Keys, Capabilities, Security) = (engineHarness, audit, keys, capabilities, security);

    public FormEngineOrchestrationTests.Harness EngineHarness { get; }
    public RecordingFormSecurityAudit Audit { get; }
    public FixedTenantKeyProvider Keys { get; }
    public StubDecryptCapabilityProvider Capabilities { get; }
    public IFormFieldSecurity Security { get; }
    public FormEngine Engine => EngineHarness.Engine;
    public FormDefinition Definition => EngineHarness.Definition;
    public InMemoryFormSubmissionState State => EngineHarness.State;

    public static async Task<FormFieldSecurityHarness> CreateAsync(
        bool decryptPermission = false,
        bool capabilityIssues = true,
        InMemoryFormSubmissionState? state = null,
        FixedTenantKeyProvider? keys = null,
        IFormFieldSecurity? security = null,
        Func<string, TenantId, FormDefinition>? definitionFactory = null,
        RecordingFormSecurityAudit? audit = null,
        string? hostJurisdiction = "US",
        IReuseResolver? reuseResolver = null)
    {
        var actualKeys = keys ?? new FixedTenantKeyProvider();
        var capabilities = new StubDecryptCapabilityProvider(capabilityIssues);
        var actualAudit = audit ?? new RecordingFormSecurityAudit();
        var actualSecurity = security ?? new TenantBoundAesGcmFormFieldSecurity(
            actualKeys, capabilities, new DefaultFormFieldGovernanceResolver(),
            new FormFieldSecurityOptions { HostJurisdiction = hostJurisdiction },
            clock: new FixedClock(FormEngineOrchestrationTests.Now));
        var roles = decryptPermission
            ? new[] { "admin", FormEnginePermissions.DecryptSensitive }
            : ["admin"];
        var harness = await FormEngineOrchestrationTests.Harness.CreateAsync(
            roles: roles,
            state: state,
            security: actualSecurity,
            readAudit: actualAudit,
            schemaJson: """{"type":"object","additionalProperties":true}""",
            definitionFactory: definitionFactory ?? CreateDefinition,
            reuseResolver: reuseResolver);
        return new(harness, actualAudit, actualKeys, capabilities, actualSecurity);
    }

    public async Task<FormSubmitReceipt> SubmitAsync(string candidate, string key)
    {
        using var document = JsonDocument.Parse(candidate);
        return await Engine.SubmitAsync(new(Definition.Id, document, key));
    }

    public async Task<JsonDocument> StoredAsync(EntityId instanceId)
    {
        var record = await EngineHarness.Store.GetAsync(Definition.Tenant, instanceId);
        return JsonDocument.Parse(record!.ProtectedAcceptedCandidate);
    }

    internal static FormDefinition CreateDefinition(string schemaId, TenantId tenant)
    {
        var fields = new Dictionary<string, FieldOverlay>(StringComparer.Ordinal)
        {
            ["displayName"] = new(InternationalizedText.FromInvariant("Display Name")),
            ["ssn"] = new(InternationalizedText.FromInvariant("SSN"), PiiSensitivity: PiiSensitivity.Sensitive),
            ["medicalId"] = new(InternationalizedText.FromInvariant("Medical ID"), PiiSensitivity: PiiSensitivity.Sensitive),
            ["cardNumber"] = Classified("Card Number", "pci"),
            ["classifiedSsn"] = Classified("Classified SSN", "pii"),
            ["caseNote"] = Classified("Case Note", "cui", ["US"]),
            ["diagnosis"] = Classified("Diagnosis", "phi", ["US"]),
            ["tagged"] = new(
                InternationalizedText.FromInvariant("Tagged"),
                Aspects: new AspectOverlay(new ClassificationAspect([new Tag("acme/labels", "secret")]))),
        };
        return new(
            new("security-form"), new(1, 0, 0), FormDefinitionStatus.Published, tenant,
            IdentityRef.System, new(schemaId),
            new(fields, [new("main", InternationalizedText.FromInvariant("Main"), fields.Keys.ToArray(), new([Harborline.Contracts.Authorization.RoleReference.Domain("admin")], [Harborline.Contracts.Authorization.RoleReference.Domain("admin")]))], []),
            null, FormEngineOrchestrationTests.Now, FormEngineOrchestrationTests.Now);
    }

    internal static FieldOverlay Classified(string label, string code, IReadOnlyList<string>? residency = null,
        string? system = null) => new(
        InternationalizedText.FromInvariant(label),
        Aspects: new AspectOverlay(
            new ClassificationAspect([new Tag(system ?? DefaultFormFieldGovernanceResolver.DataClassificationSystem, code)]),
            Lifecycle: residency is null ? null : new LifecycleAspect(Residency: new ResidencyRequirement(residency))));

    internal sealed class FixedTenantKeyProvider : IFormTenantProtectionKeyProvider
    {
        private readonly Dictionary<TenantId, FormTenantProtectionKey> _keys = new();

        public ValueTask<FormTenantProtectionKey?> GetCurrentAsync(TenantId tenant, string keyDomain, CancellationToken cancellationToken = default) =>
            ValueTask.FromResult<FormTenantProtectionKey?>(GetOrCreate(tenant));

        public ValueTask<FormTenantProtectionKey?> GetAsync(TenantId tenant, string keyDomain, string keyVersion, CancellationToken cancellationToken = default)
        {
            var key = GetOrCreate(tenant);
            return ValueTask.FromResult<FormTenantProtectionKey?>(
                string.Equals(keyDomain, TenantBoundAesGcmFormFieldSecurity.FieldEncryptionKeyDomain, StringComparison.Ordinal) &&
                string.Equals(key.KeyVersion, keyVersion, StringComparison.Ordinal) ? key : null);
        }

        private FormTenantProtectionKey GetOrCreate(TenantId tenant)
        {
            if (_keys.TryGetValue(tenant, out var key)) return key;
            var material = System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes($"test-only:{tenant}"));
            return _keys[tenant] = new("test-key-1", material);
        }
    }

    internal sealed class StubDecryptCapabilityProvider(bool issues) : IFormDecryptCapabilityProvider
    {
        public List<string> Purposes { get; } = [];
        public ValueTask<FormDecryptCapability?> AcquireAsync(TenantId tenant, string purpose, TimeSpan lifetime, CancellationToken cancellationToken = default)
        {
            Purposes.Add(purpose);
            return ValueTask.FromResult<FormDecryptCapability?>(issues
                ? new("cap:test", tenant, purpose, FormEngineOrchestrationTests.Now.Add(lifetime))
                : null);
        }
    }

    internal sealed class RecordingFormSecurityAudit : IFormSensitiveReadAudit
    {
        public List<FormSensitiveReadAudit> Appends { get; } = [];
        public ValueTask AppendAsync(FormSensitiveReadAudit audit, CancellationToken cancellationToken = default)
        {
            Appends.Add(audit);
            return ValueTask.CompletedTask;
        }
    }

    internal sealed class FixedClock(DateTimeOffset instant) : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => instant;
    }
}

using System.Text.Json;
using System.Text.Json.Nodes;

using Harborline.Foundation.Assets.Common;
using Harborline.Foundation.RuleEngine.Compilation;
using Harborline.Foundation.RuleEngine.Environments;
using Harborline.Foundation.RuleEngine.Graph;

using State = Harborline.Foundation.Forms.Models;

using Xunit;

namespace Harborline.Foundation.Forms.Engine.Tests;

/// <summary>T-590 slice 2: the concrete Forms callers present Forms' own admitted declaration.</summary>
public sealed class FormsExpressionEnvironmentTests
{
    [Fact(DisplayName = "rules-eng-26, rules-ck-28: Forms' declaration (forms-ck-13) is admitted for render and submission and its unadmitted counterparts refuse")]
    public void Forms_declaration_is_admitted_and_its_counterparts_refuse()
    {
        var declaration = FormsExpressionEnvironment.Declaration;
        Assert.Equal("forms-ck-13", declaration.Borrower);
        Assert.Equal([BorrowerEnvironmentAdmission.FieldRead], declaration.Effects);
        Assert.Equal(["caller", "candidate", "clock", "field", "record_type", "row"], declaration.Variables.Keys.Order(StringComparer.Ordinal));

        var rule = new Harborline.Contracts.Forms.RuleDefinition
        {
            Id = "t", Tier = Harborline.Contracts.Forms.RuleTier.JsonLogic, Scope = Harborline.Contracts.Forms.RuleScope.Field,
            ScopeTarget = "total", Expression = """{"+":[{"var":"a"},1]}""", Action = Harborline.Contracts.Forms.RuleActionKind.Compute,
        };
        var compiled = RuleCompiler.Compile([rule]);
        var instance = RuleInstance.FromJson(JsonNode.Parse("""{"a":1}""")!.AsObject());
        foreach (var phase in new[] { EvaluationPhase.Render, EvaluationPhase.Submission })
            Assert.Equal(2L, new FormRuleGraph(compiled, TimeProvider.System, FormsExpressionEnvironment.Admitted.For(phase))
                .EvaluateInstance(instance).Values["field:total"].Value!.GetValue<long>());

        // A phase Forms marks inapplicable, a network effect and an unregistered function all refuse.
        Assert.Throws<BorrowerEnvironmentException>(() => FormsExpressionEnvironment.Admitted.For(EvaluationPhase.Run));
        Assert.Throws<BorrowerEnvironmentException>(() => BorrowerEnvironmentAdmission.Admit(declaration with { Effects = [.. declaration.Effects, "network"] }));
        Assert.Throws<BorrowerEnvironmentException>(() => BorrowerEnvironmentAdmission.Admit(declaration with { Operations = [.. declaration.Operations, "http.get"] }));
    }

    // ck-7 S3: Forms declares caller/clock/record_type but binds only the candidate, and `caller.x` used to
    // lower to `field.caller.x`, so a rule meant to read the authenticated principal read a client-supplied
    // "caller.x" property instead and the submission committed. The compiler now refuses the unsupplied root.
    [Theory(DisplayName = "rules-ck-28, forms-ck-13: a rule addressing an unsupplied scope root cannot read a client-supplied value of that name")]
    [InlineData("caller.role", "owner")]
    [InlineData("caller.id", "attacker")]
    [InlineData("caller", "attacker")]
    [InlineData("clock.now", "2000-01-01")]
    [InlineData("record_type.id", "spoofed")]
    public async Task Unsupplied_scope_root_does_not_read_the_candidate(string path, string spoofed)
    {
        var rule = new State.RuleDefinition("guard.root", State.RuleTier.JsonLogic, State.RuleScope.Schema, "",
            $$$"""{"==":[{"var":"{{{path}}}"},"{{{spoofed}}}"]}""", State.RuleActionKind.Validate);
        var harness = await FormEngineOrchestrationTests.Harness.CreateAsync(
            roles: ["admin"], schemaJson: """{"type":"object"}""", definitionFactory: (schema, tenant) => WithRule(schema, tenant, rule));
        // Field reads are flat, so the spoof is a top-level property literally named after the path.
        using var candidate = JsonDocument.Parse($$$"""{"name":"x","{{{path}}}":"{{{spoofed}}}"}""");

        // Before the fix the client's value satisfied the rule and the submission committed.
        var validate = await Assert.ThrowsAsync<FormEngineValidationException>(async () =>
            await harness.Engine.ValidateAsync(harness.Definition.Id, candidate));
        Assert.Equal("rule.compile.bad_grammar", Assert.Single(validate.Errors).Code);
        var submit = await Assert.ThrowsAsync<FormEngineValidationException>(async () =>
            await harness.Engine.SubmitAsync(new(harness.Definition.Id, candidate, Guid.NewGuid().ToString("N"))));
        Assert.Equal("rule.compile.bad_grammar", Assert.Single(submit.Errors).Code);
        Assert.Equal(0, (await harness.Store.CountsAsync()).Submissions);

        Assert.Throws<Harborline.Foundation.Forms.Exceptions.FormDefinitionValidationException>(() =>
            RuleCompileAdmission.ValidateOrThrow(harness.Definition));
    }

    private static State.FormDefinition WithRule(string schema, TenantId tenant, State.RuleDefinition rule)
    {
        var definition = FormEngineOrchestrationTests.Harness.CreateDefinition(schema, tenant);
        return definition with { Overlay = definition.Overlay with { Rules = [rule] } };
    }
}

using System.Text.Json;
using Harborline.Contracts.Authorization;
using Harborline.Foundation.Assets.Common;
using Harborline.Foundation.Forms.Models;
using Xunit;
using Harness = Harborline.Foundation.Forms.Engine.Tests.FormEngineOrchestrationTests.Harness;

namespace Harborline.Foundation.Forms.Engine.Tests;

/// <summary>
/// DES-0016 forms-eng-2 (T-485 slice 3): the form's own submit gate (forms-ck-4) is checked on the
/// published head before anything else is resolved, and a denied submit evaluates and writes nothing.
/// </summary>
public sealed class FormSubmitGateEngineTests
{
    private static readonly SubmitGate InspectorGate = new(Role: RoleReference.Domain("inspector"));

    [Fact(DisplayName = "forms-eng-2: a submitter who fails the form's own gate is refused before reuse or the candidate is resolved, and nothing is written")]
    public async Task FailedGateRefusesBeforeResolvingAnything()
    {
        var reuse = new CountingReuseResolver();
        var gates = new GateAccess(satisfied: false);
        var harness = await Harness.CreateAsync(definitionFactory: Gated, reuseResolver: reuse, submitGates: gates);
        using var candidate = JsonDocument.Parse("""{"name":"Ada"}""");

        await Assert.ThrowsAsync<FormEngineDeniedException>(
            async () => await harness.Engine.SubmitAsync(new(harness.Definition.Id, candidate, "idem")));

        Assert.Equal([InspectorGate], gates.Asked);
        Assert.Equal(0, reuse.Calls);
        Assert.Equal((0, 0, 0, 0), await harness.Store.CountsAsync());
    }

    [Fact(DisplayName = "forms-eng-2: a submitter who satisfies the form's own gate submits one record")]
    public async Task SatisfiedGateSubmits()
    {
        var gates = new GateAccess(satisfied: true);
        var harness = await Harness.CreateAsync(definitionFactory: Gated, submitGates: gates);
        using var candidate = JsonDocument.Parse("""{"name":"Ada"}""");

        await harness.Engine.SubmitAsync(new(harness.Definition.Id, candidate, "idem"));

        Assert.Equal([InspectorGate], gates.Asked);
        Assert.Equal(1, (await harness.Store.CountsAsync()).Submissions);
    }

    [Fact(DisplayName = "forms-eng-2: a form that declares a gate is refused when the host supplies no gate port")]
    public async Task DeclaredGateWithoutPortFailsClosed()
    {
        var harness = await Harness.CreateAsync(definitionFactory: Gated);
        using var candidate = JsonDocument.Parse("""{"name":"Ada"}""");

        await Assert.ThrowsAsync<FormEngineDeniedException>(
            async () => await harness.Engine.SubmitAsync(new(harness.Definition.Id, candidate, "idem")));
        Assert.Equal(0, (await harness.Store.CountsAsync()).Submissions);
    }

    private static FormDefinition Gated(string schemaId, TenantId tenant) =>
        Harness.CreateDefinition(schemaId, tenant) with { SubmitGate = InspectorGate };

    private sealed class GateAccess(bool satisfied) : IFormSubmitGateAccess
    {
        public List<SubmitGate> Asked { get; } = [];
        public ValueTask<bool> SatisfiesAsync(FormExecutionScope scope, FormDefinition definition, SubmitGate gate, CancellationToken cancellationToken = default)
        {
            Asked.Add(gate);
            return ValueTask.FromResult(satisfied);
        }
    }

    private sealed class CountingReuseResolver : IReuseResolver
    {
        public int Calls { get; private set; }
        public ValueTask<ResolvedFormDefinition> ResolveAsync(FormDefinition definition, CancellationToken ct = default)
        {
            Calls++;
            return ValueTask.FromResult(new ResolvedFormDefinition(definition, new Dictionary<string, ReuseProvenance>()));
        }
    }
}

