namespace Harborline.Foundation.Forms.Engine.Tests;

public sealed class SharedFieldPublicationTests
{
    [Theory]
    [InlineData("taxonomy", null)]
    [InlineData("query", null)]
    [InlineData("missing-caller", "field.value_domain_principal_required")]
    [InlineData("blank-caller", "field.value_domain_principal_required")]
    [InlineData("foreign-tenant", "field.value_domain_tenant_mismatch")]
    [InlineData("inactive-tenant", "field.value_domain_tenant_required")]
    [InlineData("no-tenant", "field.value_domain_tenant_required")]
    [InlineData("missing-kinds", "field.binding_unresolved")]
    [InlineData("missing-domains", "field.binding_unresolved")]
    [InlineData("missing-bindings", "field.binding_unresolved")]
    public async Task Publication_uses_authenticated_tenant_and_complete_field_ports(string scenario, string? code)
    {
        var host = new FieldHost
        {
            SchemaRef = "sha256:publication-fields",
            Domain = scenario == "taxonomy" ? new(TaxonomyScheme: new("scheme", "1"))
                : new(RecordQuery: new("status", "{\"==\":[{\"var\":\"enabled\"},true]}")),
            Records = new Dictionary<string, IReadOnlyList<FieldDomainMember>>
            {
                ["status"] = [new("allowed", "a", System.Text.Json.JsonSerializer.SerializeToElement(new { enabled = true })),
                    new("hidden", "b", System.Text.Json.JsonSerializer.SerializeToElement(new { enabled = false }))],
            },
        };
        var definition = Harness.CreateDefinition(host.SchemaRef, host.Tenant) with
        {
            Status = FormDefinitionStatus.Draft,
            SubmitGate = new Harborline.Contracts.Authorization.SubmitGate(
                Role: Harborline.Contracts.Authorization.RoleReference.Domain("admin")),
        };
        var services = new ServiceCollection();
        services.AddSingleton<IFormDefinitionStore, InMemoryFormDefinitionStore>();
        if (scenario != "missing-caller")
            services.AddSingleton<IAuthenticatedActorContext>(new PublicationActor(
                scenario == "foreign-tenant" ? new("foreign") : host.Tenant,
                scenario == "blank-caller" ? " " : "alice", scenario));
        if (scenario != "missing-bindings") services.AddSingleton<IFormFieldBindingSource>(host);
        if (scenario != "missing-kinds") services.AddSingleton<IFieldKindRuntime>(
            new FieldKindRuntime(new FieldKindRegistry([new("declared", "1", null)])));
        if (scenario != "missing-domains") services.AddSingleton<IFieldDomainRuntime>(new ValueDomainRuntime(host, host, TimeProvider.System));
        services.AddHarborlineFormsAuthoringPublisher();
        await using var provider = services.BuildServiceProvider(new ServiceProviderOptions { ValidateScopes = true, ValidateOnBuild = true });
        await using var scope = provider.CreateAsyncScope();
        var publisher = scope.ServiceProvider.GetRequiredService<IFormDefinitionAuthoringPublisher>();
        var store = provider.GetRequiredService<IFormDefinitionStore>();
        if (code is null)
        {
            var published = await publisher.RegisterAndPublishAsync(definition);
            Assert.Equal(FormDefinitionStatus.Published, published.Status);
            Assert.NotNull(await store.GetCurrentPublishedAsync(host.Tenant, definition.Id));
            Assert.NotEmpty(host.Actors);
            Assert.All(host.Actors, actor => Assert.Equal("alice", actor));
        }
        else
        {
            var error = await Assert.ThrowsAsync<FieldAdmissionException>(() => publisher.RegisterAndPublishAsync(definition).AsTask());
            Assert.Contains(error.Refusals, refusal => refusal.Code == code);
            Assert.Null(await store.GetCurrentPublishedAsync(host.Tenant, definition.Id));
            await Assert.ThrowsAsync<FormDefinitionNotFoundException>(() => store.GetAsync(host.Tenant, definition.Id, definition.Version).AsTask());
        }
    }

    [Theory]
    [InlineData("taxonomy", "field.value_domain_source_unresolved")]
    [InlineData("query", "field.value_domain_source_unresolved")]
    [InlineData("widening", "field.value_domain_widened")]
    public async Task Bound_publication_refuses_unresolved_or_widened_domain_before_any_persistence(
        string scenario, string expectedCode)
    {
        var host = new FieldHost
        {
            SchemaRef = "sha256:publication-fields",
            Domain = scenario switch
            {
                "taxonomy" => new(TaxonomyScheme: new("missing-scheme", "1")),
                "query" => new(RecordQuery: new("missing-record-type", "true")),
                _ => new(LiteralValues: ["allowed", "hidden"]),
            },
        };
        var definition = Harness.CreateDefinition(host.SchemaRef, host.Tenant) with
        {
            Status = FormDefinitionStatus.Draft,
            SubmitGate = new Harborline.Contracts.Authorization.SubmitGate(
                Role: Harborline.Contracts.Authorization.RoleReference.Domain("admin")),
            Authoring = scenario == "widening"
                ? new(new Dictionary<string, FormFieldAuthoringMetadata>
                {
                    ["name"] = new("text", true, options: ["outside"]),
                    ["secret"] = new("text", false),
                })
                : null,
        };
        var services = new ServiceCollection();
        services.AddSingleton<IFormDefinitionStore, InMemoryFormDefinitionStore>();
        services.AddSingleton<IAuthenticatedActorContext>(new PublicationActor(host.Tenant));
        services.AddSingleton<IFormFieldBindingSource>(host);
        services.AddSingleton<IFieldKindRuntime>(new FieldKindRuntime(new FieldKindRegistry(
            [new("declared", "1", null, FieldScalarValueShape.Text)])));
        services.AddSingleton<IFieldDomainRuntime>(new ValueDomainRuntime(host, host, TimeProvider.System));
        services.AddHarborlineFormsAuthoringPublisher();
        await using var provider = services.BuildServiceProvider(
            new ServiceProviderOptions { ValidateScopes = true, ValidateOnBuild = true });
        await using var scope = provider.CreateAsyncScope();
        var publisher = scope.ServiceProvider.GetRequiredService<IFormDefinitionAuthoringPublisher>();
        var store = provider.GetRequiredService<IFormDefinitionStore>();

        var error = await Assert.ThrowsAsync<FieldAdmissionException>(
            () => publisher.RegisterAndPublishAsync(definition).AsTask());

        Assert.Contains(error.Refusals, refusal => refusal.Code == expectedCode && refusal.JsonPointer == "/name");
        Assert.Null(await store.GetCurrentPublishedAsync(definition.Tenant, definition.Id));
        await Assert.ThrowsAsync<FormDefinitionNotFoundException>(
            () => store.GetAsync(definition.Tenant, definition.Id, definition.Version).AsTask());
    }

    private sealed class PublicationActor(TenantId tenant, string userId = "alice", string scenario = "") : IAuthenticatedActorContext
    {
        public string UserId => userId;
        public IReadOnlyList<string> Roles => ["admin"];
        public TenantMetadata? Tenant { get; } = scenario == "no-tenant" ? null : new()
        {
            Id = tenant,
            Name = "Publication tenant",
            Status = scenario == "inactive-tenant" ? TenantStatus.Suspended : TenantStatus.Active,
        };
    }
}

using System.Text.Json;
using Harborline.Foundation.Forms.Models;
using Xunit;

namespace Harborline.Foundation.Forms.Engine.Tests;

public sealed class SubmissionBindingHeaderTests
{
    [Fact]
    public async Task SaveAsync_StampsBindingHeader_OnTheMintAuditEnvelope()
    {
        var harness = await FormEngineOrchestrationTests.Harness.CreateAsync();
        using var candidate = JsonDocument.Parse("""{"name":"Ada"}""");

        await harness.Engine.SubmitAsync(new(harness.Definition.Id, candidate, "binding"));

        using var payload = AuditPayload(harness);
        var binding = payload.RootElement.GetProperty("binding");
        Assert.Equal(harness.Definition.SchemaRef.Value, binding.GetProperty("schemaRef").GetString());
        Assert.Equal(harness.Definition.Id.Value, binding.GetProperty("definitionId").GetString());
        Assert.Equal("1.0.0", binding.GetProperty("definitionVersion").GetString());
        Assert.Equal("harborline-jsonlogic/v1", binding.GetProperty("engineVersion").GetString());
        Assert.Equal(["en"], Locales(binding));
        Assert.Equal(FormEngineOrchestrationTests.Now, binding.GetProperty("submittedAt").GetDateTimeOffset());
    }

    [Fact]
    public async Task SaveAsync_BindingHeaderLocaleChain_ComesFromEngineOptions()
    {
        var harness = await FormEngineOrchestrationTests.Harness.CreateAsync(
            options: new FormEngineOptions { LocaleChain = ["ar-AE", "en"] });
        using var candidate = JsonDocument.Parse("""{"name":"Ada"}""");

        await harness.Engine.SubmitAsync(new(harness.Definition.Id, candidate, "locales"));

        using var payload = AuditPayload(harness);
        Assert.Equal(["ar-AE", "en"], Locales(payload.RootElement.GetProperty("binding")));
    }

    [Fact]
    public async Task SaveAsync_PreservesPreD3TopLevelKeys_ForBackCompat()
    {
        var harness = await FormEngineOrchestrationTests.Harness.CreateAsync();
        using var candidate = JsonDocument.Parse("""{"name":"Ada","secret":"classified"}""");

        await harness.Engine.SubmitAsync(new(harness.Definition.Id, candidate, "compat"));

        using var payload = AuditPayload(harness);
        var root = payload.RootElement;
        Assert.Equal("form-instance-mint", root.GetProperty("op").GetString());
        Assert.Equal(harness.Definition.Id.Value, root.GetProperty("form").GetString());
        Assert.Equal("1.0.0", root.GetProperty("version").GetString());
        Assert.Contains("secret", root.GetProperty("encryptedFields").EnumerateArray().Select(row => row.GetString()));
    }

    [Fact]
    public async Task SaveAsync_OrdinarySubmission_CarriesNoSnapshot()
    {
        var harness = await FormEngineOrchestrationTests.Harness.CreateAsync();
        using var candidate = JsonDocument.Parse("""{"name":"Ada"}""");

        await harness.Engine.SubmitAsync(new(harness.Definition.Id, candidate, "ordinary"));

        using var payload = AuditPayload(harness);
        Assert.False(payload.RootElement.TryGetProperty("snapshot", out _));
    }

    // Ticket 288 slice 2 renamed the capture-policy coding system. The vocabulary did not change, so an
    // overlay authored under either spelling must still ask for the full projection snapshot.
    [Theory]
    [InlineData(FormEngine.CapturePolicySystem)]
    [InlineData(FormEngine.LegacyCapturePolicySystem)]
    public async Task SaveAsync_ComplianceGradeForm_CapturesFullProjectionSnapshot(string capturePolicySystem)
    {
        var harness = await FormEngineOrchestrationTests.Harness.CreateAsync(definitionFactory: (schemaId, tenant) =>
        {
            var definition = FormEngineOrchestrationTests.Harness.CreateDefinition(schemaId, tenant);
            return definition with
            {
                Overlay = definition.Overlay with
                {
                    Aspects = new AspectOverlay(new ClassificationAspect(
                        [new Tag(capturePolicySystem, "capture-as-shown")]))
                }
            };
        });
        using var candidate = JsonDocument.Parse("""{"name":"Ada","secret":"never-in-audit"}""");

        await harness.Engine.SubmitAsync(new(harness.Definition.Id, candidate, "compliance"));

        using var payload = AuditPayload(harness);
        var snapshot = payload.RootElement.GetProperty("snapshot");
        Assert.Equal("full-projection", snapshot.GetProperty("mode").GetString());
        Assert.Equal(FormEngineOrchestrationTests.Now, snapshot.GetProperty("capturedAt").GetDateTimeOffset());
        Assert.True(snapshot.GetProperty("projection").GetProperty("protected").GetBoolean());
        Assert.DoesNotContain("never-in-audit", payload.RootElement.GetRawText(), StringComparison.Ordinal);
    }

    private static JsonDocument AuditPayload(FormEngineOrchestrationTests.Harness harness)
    {
        var audit = Assert.Single(harness.State.Audits.Values);
        return JsonDocument.Parse(audit.Payload);
    }

    private static string[] Locales(JsonElement binding) =>
        binding.GetProperty("localeChain").EnumerateArray().Select(row => row.GetString()!).ToArray();
}

using Harborline.Foundation.Assets.Common;
using Harborline.Foundation.Forms.Engine.Persistence;
using Harborline.Foundation.Forms.Models;
using Xunit;

namespace Harborline.Foundation.Forms.Engine.Tests;

public sealed class SubmissionTransactionStoreTests
{
    private static readonly TenantId Tenant = new("tenant-engine");

    [Fact]
    public async Task SaveAsync_AuditFailureLeavesNoSubmissionOrOutbox()
    {
        var state = new InMemoryFormSubmissionState();
        var store = new InMemoryFormSubmissionStore(state, _ => new IOException("injected"));
        await Assert.ThrowsAsync<IOException>(async () => await store.CommitAsync(Commit("key", "fingerprint")));
        Assert.Equal((0, 0, 0, 0), await store.CountsAsync());
    }

    [Fact]
    public async Task SaveAsync_SameIdempotencyKeyAndFingerprint_ReturnsOriginalReceipt()
    {
        var store = new InMemoryFormSubmissionStore();
        var first = await store.CommitAsync(Commit("key", "same"));
        var replay = await store.CommitAsync(Commit("key", "same", localPart: "different"));
        Assert.Equal(FormSubmissionCommitDisposition.Created, first.Disposition);
        Assert.Equal(FormSubmissionCommitDisposition.Replayed, replay.Disposition);
        Assert.Equal(first.Receipt, replay.Receipt);
        Assert.Equal((1, 1, 1, 0), await store.CountsAsync());
    }

    [Fact]
    public async Task SaveAsync_SameIdempotencyKeyDifferentFingerprint_Conflicts()
    {
        var store = new InMemoryFormSubmissionStore();
        await store.CommitAsync(Commit("key", "first"));
        var conflict = await store.CommitAsync(Commit("key", "different", localPart: "other"));
        Assert.Equal(FormSubmissionCommitDisposition.Conflict, conflict.Disposition);
        Assert.Null(conflict.Receipt);
        Assert.Equal((1, 1, 1, 0), await store.CountsAsync());
    }

    [Fact]
    public async Task SaveAsync_ConcurrentSameKey_CreatesOneSubmissionAuditAndOutbox()
    {
        var store = new InMemoryFormSubmissionStore();
        var results = await Task.WhenAll(Enumerable.Range(0, 32).Select(_ => store.CommitAsync(Commit("key", "same")).AsTask()));
        Assert.Single(results, result => result.Disposition == FormSubmissionCommitDisposition.Created);
        Assert.Equal(31, results.Count(result => result.Disposition == FormSubmissionCommitDisposition.Replayed));
        Assert.Equal((1, 1, 1, 0), await store.CountsAsync());
    }

    [Fact]
    public async Task Pending_outbox_survives_adapter_reconstruction_and_completes_once()
    {
        var state = new InMemoryFormSubmissionState();
        var first = new InMemoryFormSubmissionStore(state);
        await first.CommitAsync(Commit("key", "same"));
        await first.ReleaseProjectionLeaseAsync("outbox-instance");
        var restarted = new InMemoryFormSubmissionStore(state);
        var row = Assert.Single(await restarted.LeasePendingAsync(10));
        await restarted.RetryProjectionAsync(row.OutboxId, "projection.unavailable");
        var retried = Assert.Single(await restarted.LeasePendingAsync(10));
        Assert.Equal(1, retried.Attempts);
        await restarted.CompleteProjectionAsync(row.OutboxId, Array.Empty<FormProjectionSkip>());
        await restarted.CompleteProjectionAsync(row.OutboxId, Array.Empty<FormProjectionSkip>());
        Assert.Empty(await restarted.LeasePendingAsync(10));
        Assert.Equal((1, 1, 0, 1), await restarted.CountsAsync());
    }

    [Fact]
    public async Task SubmissionScope_RejectsSecondCommitAndCommitAfterDisposal()
    {
        var store = new InMemoryFormSubmissionStore();
        var scope = await store.BeginTransactionAsync();
        await scope.CommitAsync(Commit("scope", "once"));
        await Assert.ThrowsAsync<InvalidOperationException>(async () => await scope.CommitAsync(Commit("scope-second", "twice")));
        await scope.DisposeAsync();
        await Assert.ThrowsAsync<ObjectDisposedException>(async () => await scope.CommitAsync(Commit("scope-disposed", "never")));

        Assert.Equal((1, 1, 1, 0), await store.CountsAsync());
    }

    private static FormSubmissionCommit Commit(string key, string fingerprint, string localPart = "instance")
    {
        var instant = DateTimeOffset.Parse("2026-08-08T12:00:00Z");
        var instance = new EntityId("harborline", "forms", localPart);
        return new(
            key,
            new(instance, Tenant, Guid.Parse("11111111-1111-1111-1111-111111111111"), "alice", new("inspection"), new(1, 0, 0), fingerprint, "{\"protected\":true}"u8.ToArray(), instant),
            new($"audit-{localPart}", instance, Tenant, "alice", "{\"op\":\"submit\"}"u8.ToArray(), instant),
            new($"outbox-{localPart}", instance, Tenant, Guid.Parse("11111111-1111-1111-1111-111111111111"), "alice",
                new("inspection"), new(1, 0, 0), "case-1", "{\"accepted\":true}"u8.ToArray(), instant),
            new(instance, instant, FormProjectionStatus.Pending, Array.Empty<FormProjectionSkip>()));
    }
}

using System.Text.Json;
using Harborline.Contracts.Authorization;
using Harborline.Foundation.Assets.Common;
using Harborline.Foundation.Forms.Models;
using Harborline.Kernel.SchemaValidation;
using Xunit;

namespace Harborline.Foundation.Forms.Engine.Tests;

public sealed class ValidationParityCorpusTests
{
    private static readonly string CorpusPath = Path.Combine(AppContext.BaseDirectory, "ValidationParityCorpus", "cases.json");

    public static IEnumerable<object[]> Cases()
    {
        using var corpus = JsonDocument.Parse(File.ReadAllText(CorpusPath));
        foreach (var row in corpus.RootElement.GetProperty("cases").EnumerateArray())
        {
            var expected = row.GetProperty("expected");
            var codes = expected.TryGetProperty("errorCodesServer", out var serverCodes)
                ? serverCodes.EnumerateArray().Select(value => value.GetString()!).ToArray()
                : expected.GetProperty("errorCodes").EnumerateArray().Select(value => value.GetString()!).ToArray();
            yield return
            [
                row.GetProperty("name").GetString()!,
                row.GetProperty("candidate").GetRawText(),
                row.GetProperty("rules").EnumerateArray().Select(value => value.GetString()!).ToArray(),
                codes,
                expected.GetProperty("prunedKeys").EnumerateArray().Select(value => value.GetString()!).ToArray(),
            ];
        }
    }

    [Fact]
    public void Corpus_is_non_trivial()
    {
        var cases = Cases().ToArray();
        Assert.Equal(10, cases.Length);
        Assert.Contains(cases, row => ((string)row[0]).Contains("HIDDEN SECTION", StringComparison.Ordinal));
        Assert.Contains(cases, row => ((string)row[0]).Contains("read-only required", StringComparison.Ordinal));
        Assert.Contains(cases, row => ((string)row[0]).Contains("clean pass", StringComparison.Ordinal));
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public async Task Case_matches_expected_codes_and_pruned_keys(
        string name,
        string candidateJson,
        string[] ruleIds,
        string[] expectedCodes,
        string[] expectedPrunedKeys)
    {
        _ = name;
        using var corpus = JsonDocument.Parse(File.ReadAllText(CorpusPath));
        var schemas = new InMemorySchemaRegistry();
        var schema = await schemas.RegisterAsync(corpus.RootElement.GetProperty("schema").GetRawText());
        var definition = BuildDefinition(corpus.RootElement, schema.Id.Value, ruleIds);
        using var candidate = JsonDocument.Parse(candidateJson);
        var admin = RoleReference.Domain("admin");
        var vocabulary = RoleVocabulary.FromApi([new(
            Guid.Parse("bbbd7893-58b7-41ec-96dd-1953def39fe1"), admin, "Admin",
            new(RoleOwnerKind.Package, "forms-engine-tests"), false)]);
        using var result = await FormCandidateEvaluator.EvaluateAsync(
            new(new TenantId("tenant-engine"), Guid.Parse("11111111-1111-1111-1111-111111111111"), "alice", ["admin"], vocabulary, new HeldRoleSet([admin])),
            definition,
            candidate,
            schemas,
            FormEngineOptions.DefaultMaximumCandidateBytes,
            TimeProvider.System,
            CancellationToken.None);

        var actualCodes = result.Errors.Select(row => row.Code.HasValue ? row.Code.Value! : "").Order(StringComparer.Ordinal).ToArray();
        var accepted = result.AcceptedCandidate.RootElement.EnumerateObject().Select(row => row.Name).ToHashSet(StringComparer.Ordinal);
        var actualPruned = candidate.RootElement.EnumerateObject().Select(row => row.Name).Where(name => !accepted.Contains(name)).Order(StringComparer.Ordinal).ToArray();
        Assert.Equal(expectedCodes.Order(StringComparer.Ordinal), actualCodes);
        Assert.Equal(expectedPrunedKeys.Order(StringComparer.Ordinal), actualPruned);
    }

    private static FormDefinition BuildDefinition(JsonElement corpus, string schemaId, IReadOnlyCollection<string> selectedRules)
    {
        var fields = corpus.GetProperty("schema").GetProperty("properties").EnumerateObject()
            .ToDictionary(row => row.Name, row => new FieldOverlay(InternationalizedText.FromInvariant(row.Name)), StringComparer.Ordinal);
        var sections = corpus.GetProperty("sections").EnumerateArray().Select(section => new FormSection(
            section.GetProperty("id").GetString()!,
            InternationalizedText.FromInvariant(section.GetProperty("id").GetString()!),
            section.GetProperty("fields").EnumerateArray().Select(row => row.GetString()!).ToArray(),
            new([Harborline.Contracts.Authorization.RoleReference.Domain("admin")], [Harborline.Contracts.Authorization.RoleReference.Domain("admin")]),
            Items: section.TryGetProperty("items", out var items) ? items.EnumerateArray().Select(ToItem).ToArray() : null)).ToArray();
        var catalog = corpus.GetProperty("ruleCatalog");
        var rules = selectedRules.Select(id => ToRule(catalog.GetProperty(id))).ToArray();
        var pages = corpus.GetProperty("pages").EnumerateArray().Select(page => new FormPage(
            page.GetProperty("id").GetString()!,
            InternationalizedText.FromInvariant(page.GetProperty("id").GetString()!),
            page.GetProperty("sections").EnumerateArray().Select(row => row.GetString()!).ToArray(),
            page.TryGetProperty("visibleWhen", out var guard) ? guard.GetString() : null,
            page.TryGetProperty("checks", out var checks) ? checks.EnumerateArray().Select(row => row.GetString()!).ToArray() : null)).ToArray();
        var now = DateTimeOffset.Parse("2026-08-08T12:00:00Z");
        return new(new("parity"), new(1, 0, 0), FormDefinitionStatus.Published, new("tenant-engine"), IdentityRef.System, new(schemaId),
            new(fields, sections, rules, Pages: pages), null, now, now);
    }

    private static FormItem ToItem(JsonElement item)
    {
        var kind = item.GetProperty("kind").GetString();
        return kind switch
        {
            "field" => FormItem.OfField(item.GetProperty("key").GetString()!),
            "group" => FormItem.OfGroup(item.GetProperty("key").GetString()!, item.GetProperty("items").EnumerateArray().Select(ToItem).ToArray()),
            _ => throw new InvalidOperationException($"Unsupported corpus item kind '{kind}'."),
        };
    }

    private static RuleDefinition ToRule(JsonElement rule) => new(
        rule.GetProperty("id").GetString()!,
        Enum.Parse<RuleTier>(rule.GetProperty("tier").GetString()!),
        Enum.Parse<RuleScope>(rule.GetProperty("scope").GetString()!),
        rule.GetProperty("scopeTarget").GetString()!,
        rule.GetProperty("expression").GetString()!,
        Enum.Parse<RuleActionKind>(rule.GetProperty("action").GetString()!));
}
